INSERT INTO `scan_issue` (`id`, `result_id`, `task_id`, `repository_id`, `rule_id`, `title`, `risk_level`, `rule_type`, `file_path`, `start_line`, `end_line`, `matched_content`, `context_content`, `issue_description`, `suggestion`, `status`, `handle_comment`, `handler`, `handle_time`, `create_time`, `operator_user_id`, `operator_user_name`, `run_id`, `execution_unit_id`, `result_commit_key`) VALUES (65, 65, 7, 1, 33, '多表关联查询超过2张表', 'MEDIUM', 'AI', 'X001-userpermissions/src/main/resources/mapper/CompanyAdminMapper.xml', 32, 61, 'FROM company_admin AS ca\n      LEFT JOIN other_platform_corp AS opc ON ca.tenant_id = opc.tenant_id\n      LEFT JOIN platform_application AS pa ON pa.system_code = ca.system_code', 'FROM company_admin AS ca\n      LEFT JOIN other_platform_corp AS opc ON ca.tenant_id = opc.tenant_id\n      LEFT JOIN platform_application AS pa ON pa.system_code = ca.system_code', '文件：X001-userpermissions/src/main/resources/mapper/CompanyAdminMapper.xml；联查表：company_admin、other_platform_corp、platform_application。selectCompanyAdminList 查询关联了3张表，超过2张表的上限，可能造成查询性能下降。', '建议减少关联表数量，拆分查询或对关联字段添加索引以优化性能。', 'PENDING', NULL, NULL, NULL, '2026-08-13 10:24:10', 1, 'admin', 65, 114, 'fe80530858f31b71a8d7d8767de50bab3cdf10bc5edef446bf9a668cbf624502:0');
INSERT INTO `scan_issue` (`id`, `result_id`, `task_id`, `repository_id`, `rule_id`, `title`, `risk_level`, `rule_type`, `file_path`, `start_line`, `end_line`, `matched_content`, `context_content`, `issue_description`, `suggestion`, `status`, `handle_comment`, `handler`, `handle_time`, `create_time`, `operator_user_id`, `operator_user_name`, `run_id`, `execution_unit_id`, `result_commit_key`) VALUES (66, 65, 7, 1, 33, '多表关联查询超过2张表', 'MEDIUM', 'AI', 'X001-userpermissions/src/main/resources/mapper/CompanyAdminMapper.xml', 63, 95, 'from company_admin as ca\n        LEFT JOIN other_platform_corp AS opc ON ca.tenant_id = opc.tenant_id\n        LEFT JOIN platform_application as pa on pa.system_code = ca.system_code', 'from company_admin as ca\n        LEFT JOIN other_platform_corp AS opc ON ca.tenant_id = opc.tenant_id\n        LEFT JOIN platform_application as pa on pa.system_code = ca.system_code', '文件：X001-userpermissions/src/main/resources/mapper/CompanyAdminMapper.xml；联查表：company_admin、other_platform_corp、platform_application。selectErpCompanyList 查询关联了3张表，超过2张表的上限，可能造成查询性能下降。', '建议减少关联表数量，拆分查询或对关联字段添加索引以优化性能。', 'PENDING', NULL, NULL, NULL, '2026-08-13 10:24:10', 1, 'admin', 65, 114, 'fe80530858f31b71a8d7d8767de50bab3cdf10bc5edef446bf9a668cbf624502:1');
INSERT INTO `scan_issue` (`id`, `result_id`, `task_id`, `repository_id`, `rule_id`, `title`, `risk_level`, `rule_type`, `file_path`, `start_line`, `end_line`, `matched_content`, `context_content`, `issue_description`, `suggestion`, `status`, `handle_comment`, `handler`, `handle_time`, `create_time`, `operator_user_id`, `operator_user_name`, `run_id`, `execution_unit_id`, `result_commit_key`) VALUES (67, 65, 7, 1, 33, 'SQL多表关联查询超过2张表：selectByTenantId', 'MEDIUM', 'AI', 'X001-userpermissions/src/main/resources/mapper/OtherPlatformCorpMapper.xml', 27, 37, 'SELECT\n      opc.tenant_id, pi.platform_name as platformName\n      FROM other_platform_corp as opc\n      LEFT JOIN platform_standard as ps on ps.id = opc.package_standard_id\n      LEFT JOIN platform_identification as pi on pi.platform_sign = ps.platform_sign', 'SELECT\n      opc.tenant_id, pi.platform_name as platformName\n      FROM other_platform_corp as opc\n      LEFT JOIN platform_standard as ps on ps.id = opc.package_standard_id\n      LEFT JOIN platform_identification as pi on pi.platform_sign = ps.platform_sign', '该SQL关联了3张表（other_platform_corp、platform_standard、platform_identification），超过规则要求的2张表上限。文件：X001-userpermissions/src/main/resources/mapper/OtherPlatformCorpMapper.xml。多表关联查询可能导致查询性能下降，并增加维护复杂度。', '建议拆分查询或使用中间表，避免一次关联超过2张表；如业务需要，需确保关联字段有索引并优化查询计划。', 'PENDING', NULL, NULL, NULL, '2026-08-13 10:24:46', 1, 'admin', 65, 115, '3a37100265accef9e5fa9d05f48ca3de02aeb35728f3c90ac0ae9dcf5a4c2bd1:0');
