INSERT INTO `scan_issue` (`id`, `result_id`, `task_id`, `repository_id`, `rule_id`, `title`, `risk_level`, `rule_type`, `file_path`, `start_line`, `end_line`, `matched_content`, `context_content`, `issue_description`, `suggestion`, `status`, `handle_comment`, `handler`, `handle_time`, `create_time`, `operator_user_id`, `operator_user_name`, `run_id`, `execution_unit_id`, `result_commit_key`) VALUES (97, 97, 7, 1, 33, '配置文件包含非法字符零宽空格', 'HIGH', 'AI', 'X001-userpermissions/src/main/resources/logback-spring.xml', 32, 32, '    <appender name="allLog" class="ch.qos.logback.core.rolling.RollingFileAppender">​', '    <appender name="allLog" class="ch.qos.logback.core.rolling.RollingFileAppender">​', '第32行末尾存在零宽空格（U+200B），该字符不符合 XML 1.0 规范，会导致 logback-spring.xml 解析失败。同类的非法字符还出现在第58行和第124行，建议一并检查清理。', '删除第32、58、124行中的零宽空格，或使用十六进制编辑器检查文件，确保无不可见 Unicode 字符。', 'PENDING', NULL, NULL, NULL, '2026-08-13 10:48:52', 1, 'admin', 97, 144, '03caac4c2226e21c530138ace2efac3e7d17397a0cbdf80f6f71f1c7710c46c0:0');
INSERT INTO `scan_issue` (`id`, `result_id`, `task_id`, `repository_id`, `rule_id`, `title`, `risk_level`, `rule_type`, `file_path`, `start_line`, `end_line`, `matched_content`, `context_content`, `issue_description`, `suggestion`, `status`, `handle_comment`, `handler`, `handle_time`, `create_time`, `operator_user_id`, `operator_user_name`, `run_id`, `execution_unit_id`, `result_commit_key`) VALUES (98, 97, 7, 1, 33, '日志文件名包含多余的 .log 后缀', 'LOW', 'AI', 'X001-userpermissions/src/main/resources/logback-spring.xml', 36, 36, '<FileNamePattern>${LOG_FILE_PATH}/%d{yyyy-MM-dd}.all.log.log</FileNamePattern>', '<FileNamePattern>${LOG_FILE_PATH}/%d{yyyy-MM-dd}.all.log.log</FileNamePattern>', '该文件名模式以 .all.log.log 结尾，包含了重复的 .log。第62行和第96行也存在同样问题，可能导致日志文件名不符合预期。', '将文件名模式修改为 ${LOG_FILE_PATH}/%d{yyyy-MM-dd}.all.log，并同步修改第62行和第96行的对应配置。', 'PENDING', NULL, NULL, NULL, '2026-08-13 10:48:52', 1, 'admin', 97, 144, '03caac4c2226e21c530138ace2efac3e7d17397a0cbdf80f6f71f1c7710c46c0:1');
INSERT INTO `scan_issue` (`id`, `result_id`, `task_id`, `repository_id`, `rule_id`, `title`, `risk_level`, `rule_type`, `file_path`, `start_line`, `end_line`, `matched_content`, `context_content`, `issue_description`, `suggestion`, `status`, `handle_comment`, `handler`, `handle_time`, `create_time`, `operator_user_id`, `operator_user_name`, `run_id`, `execution_unit_id`, `result_commit_key`) VALUES (99, 97, 7, 1, 33, '同时使用 TimeBasedRollingPolicy 和 SizeBasedTriggeringPolicy', 'MEDIUM', 'AI', 'X001-userpermissions/src/main/resources/logback-spring.xml', 77, 79, '<triggeringPolicy class="ch.qos.logback.core.rolling.SizeBasedTriggeringPolicy">\n            <MaxFileSize>20MB</MaxFileSize>\n        </triggeringPolicy>', '<triggeringPolicy class="ch.qos.logback.core.rolling.SizeBasedTriggeringPolicy">\n            <MaxFileSize>20MB</MaxFileSize>\n        </triggeringPolicy>', 'TimeBasedRollingPolicy 自身已实现了滚动触发策略，额外配置 SizeBasedTriggeringPolicy 可能造成策略冲突，导致按大小滚动的配置不生效。第111-113行的 errorLog 也存在同样配置。', '移除 SizeBasedTriggeringPolicy，改为在 TimeBasedRollingPolicy 内配置 <maxFileSize> 来控制文件大小，例如 <maxFileSize>20MB</maxFileSize>。', 'PENDING', NULL, NULL, NULL, '2026-08-13 10:48:52', 1, 'admin', 97, 144, '03caac4c2226e21c530138ace2efac3e7d17397a0cbdf80f6f71f1c7710c46c0:2');
INSERT INTO `scan_issue` (`id`, `result_id`, `task_id`, `repository_id`, `rule_id`, `title`, `risk_level`, `rule_type`, `file_path`, `start_line`, `end_line`, `matched_content`, `context_content`, `issue_description`, `suggestion`, `status`, `handle_comment`, `handler`, `handle_time`, `create_time`, `operator_user_id`, `operator_user_name`, `run_id`, `execution_unit_id`, `result_commit_key`) VALUES (100, 97, 7, 1, 33, '日志路径硬编码为 Windows 路径', 'LOW', 'AI', 'X001-userpermissions/src/main/resources/logback-spring.xml', 13, 13, '<springProperty name="LOG_FILE_PATH" source="logging.file.path" defaultValue="D:/logs/xyy/${applicationName}"/>', '<springProperty name="LOG_FILE_PATH" source="logging.file.path" defaultValue="D:/logs/xyy/${applicationName}"/>', '默认日志路径为 D:/logs/xyy/${applicationName}，硬编码了 Windows 盘符，不利于跨平台部署和配置管理。', '建议将默认值改为相对路径（如 ./logs/${applicationName}），或通过环境变量/配置中心提供，避免硬编码。', 'PENDING', NULL, NULL, NULL, '2026-08-13 10:48:52', 1, 'admin', 97, 144, '03caac4c2226e21c530138ace2efac3e7d17397a0cbdf80f6f71f1c7710c46c0:3');
INSERT INTO `scan_issue` (`id`, `result_id`, `task_id`, `repository_id`, `rule_id`, `title`, `risk_level`, `rule_type`, `file_path`, `start_line`, `end_line`, `matched_content`, `context_content`, `issue_description`, `suggestion`, `status`, `handle_comment`, `handler`, `handle_time`, `create_time`, `operator_user_id`, `operator_user_name`, `run_id`, `execution_unit_id`, `result_commit_key`) VALUES (101, 97, 7, 1, 33, 'OGNL表达式空指针风险：systemCodeList未判空即调用size()', 'HIGH', 'AI', 'X001-userpermissions/src/main/resources/mapper/CompanyAccountMapper.xml', 54, 54, '<if test="systemCodeList.size() != 0 and systemCodeList!= null">', '<if test="systemCodeList.size() != 0 and systemCodeList!= null">', '在MyBatis的<if>测试中，条件顺序错误，当systemCodeList为null时，先执行size()会抛出空指针异常。', '调整条件顺序为 ''systemCodeList != null and systemCodeList.size() != 0''，确保先判空。', 'PENDING', NULL, NULL, NULL, '2026-08-13 10:49:28', 1, 'admin', 97, 145, 'aa2896147992cc96dfa605cfcfbfea87bae237555018888a3282d76a890fef0a:0');
INSERT INTO `scan_issue` (`id`, `result_id`, `task_id`, `repository_id`, `rule_id`, `title`, `risk_level`, `rule_type`, `file_path`, `start_line`, `end_line`, `matched_content`, `context_content`, `issue_description`, `suggestion`, `status`, `handle_comment`, `handler`, `handle_time`, `create_time`, `operator_user_id`, `operator_user_name`, `run_id`, `execution_unit_id`, `result_commit_key`) VALUES (102, 97, 7, 1, 33, 'OGNL表达式空指针风险：tenantIdList未判空即调用size()', 'HIGH', 'AI', 'X001-userpermissions/src/main/resources/mapper/CompanyAccountMapper.xml', 87, 87, '<if test="tenantIdList.size() != 0 and tenantIdList!= null">', '<if test="tenantIdList.size() != 0 and tenantIdList!= null">', '在MyBatis的<if>测试中，条件顺序错误，当tenantIdList为null时，先执行size()会抛出空指针异常。', '调整条件顺序为 ''tenantIdList != null and tenantIdList.size() != 0''，确保先判空。', 'PENDING', NULL, NULL, NULL, '2026-08-13 10:49:28', 1, 'admin', 97, 145, 'aa2896147992cc96dfa605cfcfbfea87bae237555018888a3282d76a890fef0a:1');
