INSERT INTO `scan_issue` (`id`, `result_id`, `task_id`, `repository_id`, `rule_id`, `title`, `risk_level`, `rule_type`, `file_path`, `start_line`, `end_line`, `matched_content`, `context_content`, `issue_description`, `suggestion`, `status`, `handle_comment`, `handler`, `handle_time`, `create_time`, `operator_user_id`, `operator_user_name`, `run_id`, `execution_unit_id`, `result_commit_key`) VALUES (129, 193, 232, 65, 65, '未使用的方法 getUniqueSources', 'INFO', 'AI', 'herolord9_disco-elysium-website/src/views/Chat.vue', 386, 399, '// 去重引用来源（按文章ID去重，每个文章只显示一次）\nconst getUniqueSources = (sources: any[]): any[] => {\n  if (!sources || !Array.isArray(sources)) return []\n  \n  const seen = new Map<number, any>()\n  for (const source of sources) {\n    const articleId = source.article_id\n    if (articleId && !seen.has(articleId)) {\n      // 保留第一个出现的引用（通常是最相关的）\n      seen.set(articleId, source)\n    }\n  }\n  \n  return Array.from(seen.values())\n}', '// 去重引用来源（按文章ID去重，每个文章只显示一次）\nconst getUniqueSources = (sources: any[]): any[] => {\n  if (!sources || !Array.isArray(sources)) return []\n  \n  const seen = new Map<number, any>()\n  for (const source of sources) {\n    const articleId = source.article_id\n    if (articleId && !seen.has(articleId)) {\n      // 保留第一个出现的引用（通常是最相关的）\n      seen.set(articleId, source)\n    }\n  }\n  \n  return Array.from(seen.values())\n}', '在文件 herolord9_disco-elysium-website/src/views/Chat.vue 中，定义了方法 getUniqueSources（第386行至第399行），但该方法在模板与脚本中均未被引用或调用，属于未使用的函数。', '建议删除未使用的 getUniqueSources 函数，或根据实际需求在模板中调用它（例如对引用来源进行去重展示），避免冗余代码。', 'CONFIRMED', '', 'system', '2026-08-14 10:11:51', '2026-08-14 09:51:30', 1, 'admin', 193, 254, '18b5071897daabb12ee311b35c5ad2ee559cef012da2aea5881ed1056eccfa23:0');
