ml version=\\"1.0\\" encoding=\\"UTF-8\\"?>\\r\\n<configuration  scan=\\"true\\" scanPeriod=\\"60 seconds\\" debug=\\"false\\">\\r\\n    <include resource=\\"org/springframework/boot/logging/logback/defaults.xml\\"/>\\r\\n\\r\\n    <contextName>my_logback</contextName>\\r\\n\\r\\n    <springProperty name=\\"applicationName\\" scope=\\"context\\" source=\\"spring.application.name\\"/>\\r\\n\\r\\n    <!-- 规范：单条日志≤4096 字节，消息部分截断 -->\\r\\n    <conversionRule conversionWord=\\"msgTruncate\\" converterClass=\\"xyy.base.logging.TruncateMessageConverter\\"/>\\r\\n\\r\\n    <!-- 规范 1.2.1：生产路径可配置；开发默认 D:/logs/xyy/${applicationName} -->\\r\\n    <springProperty name=\\"LOG_FILE_PATH\\" source=\\"logging.file.path\\" defaultValue=\\"D:/logs/xyy/${applicationName}\\"/>\\r\\n\\r\\n    <!-- 与 userserver / log_content.md 一致：timestamp | 线程 | 日志级别 | SOFA-TraceId | logger | 消息 -->\\r\\n    <property name=\\"CONSOLE_LOG_PATTERN\\"\\r\\n              value=\\"%d{yyyy-MM-dd HH:mm:ss.SSS}|%-5level|[%15.15t]|SOFA-TraceId=%X{SOFA-TraceId:-}|%logger{40}|%msgTruncate%n%wEx\\"/>\\r\\n    <property name=\\"FILE_LOG_PATTERN\\"\\r\\n              value=\\"%d{yyyy-MM-dd HH:mm:ss.SSS}|%-5level|%-15t|SOFA-TraceId=%X{SOFA-TraceId:-}|%X{local-ip:-}|%X{last-ip:-}|%X{app-name:-}|%X{cost-time:-}|%logger{50}|%msgTruncate%n%wEx\\"/>\\r\\n\\r\\n    <!-- Appender to log to console（含 SOFA-TraceId） -->\\r\\n    <appender name=\\"console\\" class=\\"ch.qos.logback.core.ConsoleAppender\\">\\r\\n        <filter class=\\"ch.qos.logback.classic.filter.ThresholdFilter\\">\\r\\n            <level>DEBUG</level>\\r\\n        </filter>\\r\\n        <encoder>\\r\\n            <pattern>${CONSOLE_LOG_PATTERN}</pattern>\\r\\n            <charset>utf8</charset>\\r\\n        </encoder>\\r\\n    </appender>\\r\\n\\r\\n    <!-- Appender to log to file -->​\\r\\n    <appender name=\\"allLog\\" class=\\"ch.qos.logback.core.rolling.RollingFileAppender\\">\\r\\n        <rollingPolicy class=\\"ch.qos.logback.core.rolling.TimeBasedRollingPolicy\\">\\r\\n            <!--日志文件输出的文件名-->\\r\\n            <FileNamePattern>${LOG_FILE_PATH}/%d{yyyy-MM-dd}.all.log.log</FileNamePattern>\\r\\n            <!--日志文件保留天数-->\\r\\n            <MaxHistory>30</MaxHistory>\\r\\n            <!-- 必须加这个回滚才会起作用 -->\\r\\n            <CleanHistoryOnStart>true</CleanHistoryOnStart>\\r\\n        </rollingPolicy>\\r\\n        <encoder class=\\"ch.qos.logback.classic.encoder.PatternLayoutEncoder\\">\\r\\n            <pattern>${FILE_LOG_PATTERN}</pattern>\\r\\n            <charset>UTF-8</charset>\\r\\n        </encoder>\\r\\n    </appender>\\r\\n\\r\\n    <!--异步到文件-->\\r\\n    <appender name=\\"asyncAllAppender\\" class=\\"ch.qos.logback.classic.AsyncAppender\\">\\r\\n        <!-- 不丢失日志.默认的,如果队列的80%已满,则会丢弃TRACT、DEBUG、INFO级别的日志 -->\\r\\n        <discardingThreshold>0</discardingThreshold>\\r\\n        <!-- 更改默认的队列的深度,该值会影响性能.默认值为256 -->\\r\\n        <queueSize>512</queueSize>\\r\\n        <!-- 添加附加的appender,最多只能添加一个 -->\\r\\n        <appender-ref ref=\\"allLog\\"/>\\r\\n    </appender>\\r\\n\\r\\n    <!-- Appender to log to file -->​\\r\\n    <appender name=\\"infoLog\\" class=\\"ch.qos.logback.core.rolling.RollingFileAppender\\">\\r\\n        <rollingPolicy class=\\"ch.qos.logback.core.rolling.TimeBasedRollingPolicy\\">\\r\\n            <!--日志文件输出的文件名-->\\r\\n            <FileNamePattern>${LOG_FILE_PATH}/%d{yyyy-MM-dd}.info.log.log</FileNamePattern>\\r\\n            <!--日志文件保留天数-->\\r\\n            <MaxHistory>30</MaxHistory>\\r\\n        </rollingPolicy>\\r\\n        <!--这里设置日志级别为info-->\\r\\n        <filter class=\\"ch.qos.logback.classic.filter.LevelFilter\\">\\r\\n            <level>info</level>\\r\\n            <onMatch>ACCEPT</onMatch>\\r\\n            <onMismatch>DENY</onMismatch>\\r\\n        </filter>\\r\\n        <encoder class=\\"ch.qos.logback.classic.encoder.PatternLayoutEncoder\\">\\r\\n            <pattern>${FILE_LOG_PATTERN}</pattern>\\r\\n            <charset>UTF-8</charset>\\r\\n        </encoder>\\r\\n        <!--日志文件最大的大小-->\\r\\n        <triggeringPolicy class=\\"ch.qos.logback.core.rolling.SizeBasedTriggeringPolicy\\">\\r\\n            <MaxFileSize>20MB</MaxFileSize>\\r\\n        </triggeringPolicy>\\r\\n    </appender>\\r\\n\\r\\n    <!--异步到文件-->\\r\\n    <appender name=\\"asyncInfoAppender\\" class=\\"ch.qos.logback.classic.AsyncAppender\\">\\r\\n        <!-- 不丢失日志.默认的,如果队列的80%已满,则会丢弃TRACT、DEBUG、INFO级别的日志 -->\\r\\n        <discardingThreshold>0</discardingThreshold>\\r\\n        <!-- 更改默认的队列的深度,该值会影响性能.默认值为256 -->\\r\\n        <queueSize>512</queueSize>\\r\\n        <!-- 添加附加的appender,最多只能添加一个 -->\\r\\n        <appender-ref ref=\\"infoLog\\"/>\\r\\n    </appender>\\r\\n\\r\\n    <!--新增加的error appender-->\\r\\n    <appender name=\\"errorLog\\"  class=\\"ch.qos.logback.core.rolling.RollingFileAppender\\">\\r\\n        <rollingPolicy class=\\"ch.qos.logback.core.rolling.TimeBasedRollingPolicy\\">\\r\\n            <!--日志文件输出的文件名-->\\r\\n            <FileNamePattern>${LOG_FILE_PATH}/%d{yyyy-MM-dd}.error.log.log</FileNamePattern>\\r\\n            <!--日志文件保留天数-->\\r\\n            <MaxHistory>30</MaxHistory>\\r\\n        </rollingPolicy>\\r\\n        <!--这里设置日志级别为error-->\\r\\n        <filter class=\\"ch.qos.logback.classic.filter.LevelFilter\\">\\r\\n            <level>error</level>\\r\\n            <onMatch>ACCEPT</onMatch>\\r\\n            <onMismatch>DENY</onMismatch>\\r\\n        </filter>\\r\\n        <encoder class=\\"ch.qos.logback.classic.encoder.PatternLayoutEncoder\\">\\r\\n            <pattern>${FILE_LOG_PATTERN}</pattern>\\r\\n            <charset>UTF-8</charset>\\r\\n        </encoder>\\r\\n        <!--日志文件最大的大小-->\\r\\n        <triggeringPolicy class=\\"ch.qos.logback.core.rolling.SizeBasedTriggeringPolicy\\">\\r\\n            <MaxFileSize>20MB</MaxFileSize>\\r\\n        </triggeringPolicy>\\r\\n    </appender>\\r\\n\\r\\n    <appender name=\\"asyncErrorAppender\\" class=\\"ch.qos.logback.classic.AsyncAppender\\">\\r\\n        <!-- 不丢失日志.默认的,如果队列的80%已满,则会丢弃TRACT、DEBUG、INFO级别的日志 -->\\r\\n        <discardingThreshold>0</discardingThreshold>\\r\\n        <!-- 更改默认的队列的深度,该值会影响性能.默认值为256 -->\\r\\n        <queueSize>512</queueSize>\\r\\n        <!-- 添加附加的appender,最多只能添加一个 -->\\r\\n        <appender-ref ref=\\"errorLog\\"/>\\r\\n    </appender>\\r\\n    ​\\r\\n    <!-- Appender to log to file in a JSON format -->\\r\\n    <appender name=\\"logStash\\" class=\\"ch.qos.logback.core.rolling.RollingFileAppender\\">\\r\\n        <rollingPolicy class=\\"ch.qos.logback.core.rolling.TimeBasedRollingPolicy\\">\\r\\n            <fileNamePattern>${LOG_FILE_PATH}/%d{yyyy-MM-dd}.json.log</fileNamePattern>\\r\\n            <maxHistory>30</maxHistory>\\r\\n        </rollingPolicy>\\r\\n        <encoder class=\\"net.logstash.logback.encoder.LoggingEventCompositeJsonEncoder\\">\\r\\n            <providers>\\r\\n                <timestamp>\\r\\n                    <timeZone>UTC</timeZone>\\r\\n                </timestamp>\\r\\n                <pattern>\\r\\n                    <pattern>\\r\\n                        {\\r\\n                        \\"severity\\": \\"%level\\",\\r\\n                        \\"service\\": \\"${applicationName:-}\\",\\r\\n                        \\"SOFA-TraceId\\": \\"%X{SOFA-TraceId:-}\\",\\r\\n                        \\"pid\\": \\"${PID:-}\\",\\r\\n                        \\"thread\\": \\"%thread\\",\\r\\n                        \\"class\\": \\"%logger{40}\\",\\r\\n                        \\"rest\\": \\"%message\\"\\r\\n                        }\\r\\n                    </pattern>\\r\\n                </pattern>\\r\\n            </providers>\\r\\n        </encoder>\\r\\n    </appender>\\r\\n\\r\\n    <root level=\\"info\\">\\r\\n        <appender-ref ref=\\"console\\" />\\r\\n        <appender-ref ref=\\"asyncAllAppender\\" />\\r\\n        <appender-ref ref=\\"asyncInfoAppender\\" />\\r\\n        <appender-ref ref=\\"asyncErrorAppender\\" />\\r\\n        <appender-ref ref=\\"logStash\\" />\\r\\n    </root>\\r\