\\n        ca.admin_name,\\r\\n        ca.company_name,\\r\\n        ca.company_code,\\r\\n        ca.tenant_id,\\r\\n        ca.tenant_photo,\\r\\n        ca.create_time,\\r\\n        ca.update_time,\\r\\n        ca.status,\\r\\n        ca.be_logoff,\\r\\n        ca.system_code,\\r\\n        ca.email,\\r\\n        ca.corp_province,\\r\\n        ca.corp_city,\\r\\n        bu.real_name as realName,\\r\\n        ca.company_name as organizeName,\\r\\n        bu.enabled_mark as enabledMark,\\r\\n        bu.creator_time as createTime,\\r\\n        bu.id as userId\\r\\n        FROM  base_user AS bu\\r\\n        LEFT JOIN company_admin AS ca ON ca.tenant_id = bu.tenant_id\\r\\n        <where>\\r\\n            <if test=\\"tenantId != null and tenantId != ''''\\">and ca.tenant_id like concat(#{tenantId},''%'')</if>\\r\\n            <if test=\\"realName != null and realName != ''''\\">and bu.real_name like concat(#{realName},''%'')</if>\\r\\n            <if test=\\"organizeName != null and organizeName != ''''\\">and ca.company_name like concat(#{organizeName},''%'')</if>\\r\\n            <if test=\\"account != null and account != ''''\\">and bu.account = #{account}</if>\\r\\n            <if test=\\"systemCodeList.size() != 0 and systemCodeList!= null\\">\\r\\n                and ca.system_code in\\r\\n                <foreach collection=\\"systemCodeList\\" open=\\"(\\" separator=\\",\\" close=\\")\\" item=\\"item\\">\\r\\n                    #{item}\\r\\n                </foreach>\\r\\n            </if>\\r\\n        </where>\\r\\n        ORDER BY bu.creator_time DESC\\r\\n    </select>\\r\\n\\r\\n\\r\\n    <select id=\\"getUserList\\" resultMap=\\"BaseResultMap\\">\\r\\n        SELECT\\r\\n        ca.id,\\r\\n        ca.company_code,\\r\\n        ca.company_name,\\r\\n        bu.account,\\r\\n        bu.tenant_id,\\r\\n        ca.system_code,\\r\\n        bu.enabled_mark AS enabled,\\r\\n        bu.email,\\r\\n        bu.user_type,\\r\\n        bu.id AS accountId,\\r\\n    