YPE mapper PUBLIC \\"-//mybatis.org//DTD Mapper 3.0//EN\\" \\"http://mybatis.org/dtd/mybatis-3-mapper.dtd\\">\\r\\n<mapper namespace=\\"xyy.base.mapper.CompanyAdminMapper\\">\\r\\n  <resultMap id=\\"BaseResultMap\\" type=\\"xyy.base.entity.CompanyAdminEntity\\">\\r\\n    <id column=\\"id\\" jdbcType=\\"BIGINT\\" property=\\"id\\" />\\r\\n    <result column=\\"account\\" jdbcType=\\"VARCHAR\\" property=\\"account\\" />\\r\\n    <result column=\\"admin_name\\" jdbcType=\\"VARCHAR\\" property=\\"adminName\\" />\\r\\n    <result column=\\"company_name\\" jdbcType=\\"VARCHAR\\" property=\\"companyName\\" />\\r\\n    <result column=\\"company_code\\" jdbcType=\\"VARCHAR\\" property=\\"companyCode\\" />\\r\\n    <result column=\\"tenant_id\\" jdbcType=\\"VARCHAR\\" property=\\"tenantId\\" />\\r\\n    <result column=\\"tenant_photo\\" jdbcType=\\"VARCHAR\\" property=\\"tenantPhoto\\" />\\r\\n    <result column=\\"create_time\\" jdbcType=\\"TIMESTAMP\\" property=\\"createTime\\" />\\r\\n    <result column=\\"update_time\\" jdbcType=\\"TIMESTAMP\\" property=\\"updateTime\\" />\\r\\n    <result column=\\"status\\" jdbcType=\\"BIT\\" property=\\"status\\" />\\r\\n    <result column=\\"be_logoff\\" jdbcType=\\"BIT\\" property=\\"beLogoff\\" />\\r\\n    <result column=\\"system_code\\" jdbcType=\\"VARCHAR\\" property=\\"systemCode\\" />\\r\\n    <result column=\\"email\\" jdbcType=\\"VARCHAR\\" property=\\"email\\" />\\r\\n    <result column=\\"corp_province\\" jdbcType=\\"VARCHAR\\" property=\\"corpProvince\\" />\\r\\n    <result column=\\"corp_city\\" jdbcType=\\"VARCHAR\\" property=\\"corpCity\\" />\\r\\n\\r\\n    <result column=\\"systemName\\" jdbcType=\\"VARCHAR\\" property=\\"systemName\\" />\\r\\n    <result column=\\"startTime\\" jdbcType=\\"VARCHAR\\" property=\\"startTime\\" />\\r\\n    <result column=\\"endTime\\" jdbcType=\\"VARCHAR\\" property=\\"endTime\\" />\\r\\n    <result column=\\"channel\\" jdbcType=\\"VARCHAR\\" property=\\"channel\\" />\\r\\n\\r\\n\\r\\n  </resultMap>\\r\\n  <sql id=\\"Base_Column_List\\">\\r\\n    id, account, admin_name, company_name, company_code, tenant_id, tenant_photo, create_time, \\r\\n    update_time, status,be_logoff, system_code, email, corp_province, corp_city\\r\\n  </sql>\\r\\n  <select id=\\"selectCompanyAdminList\\" resultMap=\\"BaseResultMap\\">\\r\\n      SELECT\\r\\n      <include refid=\\"Base_Column_List\\"/>,\\r\\n      opc.start_time as startTime,\\r\\n      opc.end_time as endTime,\\r\\n      pa.system_name as systemName,\\r\\n      opc.channel as channel\\r\\n      FROM company_admin AS ca\\r\\n      LEFT JOIN other_platform_corp AS opc ON ca.tenant_id = opc.tenant_id\\r\\n      LEFT JOIN platform_application AS pa ON pa.system_code = ca.system_code\\r\\n      <where>\\r\\n          1 = 1 and be_logoff=1\\r\\n          <if test=\\"startMinTime != null and startMinTime != ''''\\">and opc.start_time &gt;= #{startMinTime}</if>\\r\\n          <if test=\\"startMaxTime != null and startMaxTime != ''''\\">and opc.start_time &lt;= #{startMaxTime}</if>\\r\\n          <if test=\\"endMinTime != null and endMinTime != ''''\\">and opc.end_time &gt;= #{endMinTime}</if>\\r\\n          <if test=\\"endMaxTime != null and endMaxTime != ''''\\">and opc.end_time &lt;= #{endMaxTime}</if>\\r\\n          <if test=\\"tenantId != null and tenantId != ''''\\">and ca.tenant_id like concat(#{tenantId},''%'')</if>\\r\\n          <if test=\\"companyName != null and companyName != ''''\\">and ca.company_name like concat(#{companyName},''%'')</if>\\r\\n          <if test=\\"systemName != null and systemName != ''''\\">and pa.system_name like concat(#{systemName},''%'')</if>\\r\\n          <if test=\\"status != null and status != ''''\\">and ca.status = #{status}</if>\\r\\n          <if test=\\"systemCodeList.size() != 0 and systemCodeList!= null\\">\\r\\n            and ca.system_code in\\r\\n            <foreach collection=\\"systemCodeList\\" open=\\"(\\" separator=\\",\\" close=\\")\\" item=\\"item\\">\\r\\n                #{item}\\r\\n            </foreach>\\r\\n          </if>\\r\\n      </where>\\r\\n\\r\\n      ORDER BY ca.create_time DESC\\r\\n  </select>\\r\\n\\r\\n    <select id=\\"selectErpCompanyList\\" resultMap=\\"BaseResultMap\\">\\r\\n        select\\r\\n        <include refid=\\"Base_Column_List\\"/>,\\r\\n        pa.system_name,\\r\\n        opc.channel as channel\\r\\n        from company_admin as ca\\r\\n        LEFT JOIN other_platform_corp AS opc ON ca.tenant_id = opc.tenant_id\\r\\n        LEFT JOIN platform_application as pa on pa.system_code = ca.system_code\\r\\n        <where>\\r\\n            1 = 1  and be_logoff=1\\r\\n            <if test=\\"companyName != null and companyName != ''''\\">and ca.company_name like concat(#{companyName},''%'') </if>\\r\\n            <if test=\\"tenantId != null and tenantId != ''''\\">and ca.tenant_id like concat(#{tenantId},''%'')</if>\\r\\n            <if test=\\"userName != null and userName != ''''\\">and ca.admin_name like concat(#{userName},''%'')</if>\\r\\n            <if test=\\"userCode != null and userCode != ''''\\">and ca.account like concat(#{userCode},''%'')</if>\\r\\n            <if test=\\"province != null and province != ''''\\">and ca.corp_province like concat(#{province},''%'')</if>\\r\\n            <if test=\\"city != null and city != ''''\\">and ca.corp_city like concat(#{city},''%'')</if>\\r\\n            <if test=\\"startTime != null and startTime != ''''\\">and ca.create_time &gt;= #{startTime}</if>\\r\\n            <if test=\\"endTime != null and endTime != ''''\\">and ca.create_time &lt;= #{endTime}</if>\\r\\n            <if test=\\"systemCodeList.size() != 0 and systemCodeList!= null\\">\\r\\n                and pa.system_code in\\r\\n                <foreach\\r\\n                        collection=\\"systemCodeList\\" open=\\"(\\" separator=\\",\\" close=\\")\\" item=\\"item\\">#{item}\\r\\n                </foreach>\\r\\n            </if>\\r\\n            <if test=\\"sourceIds.size() != 0 and sourceIds!= null\\">\\r\\n                and ca.tenant_id in\\r\\n                <foreach\\r\\n                        collection=\\"sourceIds\\" open=\\"(\\" separator=\\",\\" close=\\")\\" item=\\"item\\">#{item}\\r\\n                </foreach>\\r\\n            </if>\\r\\n            order by ca.create_time desc\\r\\n        </where>\\r\\n    </select>\\r\\n</mapper>"}],"temperature":0,"response_format":{"type":"json_object"}},"rawResponse":{"id":"68c2c204-12bc-41c9-be09-819fc09ed8f5","object":"chat.completion","created":1786587803,"model":"deepseek-v4-flash","choices":[{"index":0,"message":{"role":"assistant","content":"{\\n  \\"issues\\": [\\n    {\\n      \\"title\\": \\"多表关联查询超过2张表\\",\\n      \\"severity\\": \\"MEDIUM\\",\\n      \\"startLine\\": 32,\\n      \\"endLine\\": 61,\\n      \\"evidence\\": \\"FROM company_admin AS ca\\\\n      LEFT JOIN other_platform_corp AS opc ON ca.tenant_id = opc.tenant_id\\\\n      LEFT JOIN platform_application AS pa ON pa.system_code = ca.system_code\\",\\n      \\"description\\": \\"selectCompanyAdminList 查询关联了 company_admin、other_platform_corp、platform_application 共3张表，超过2张表的上限，可能造成查询性能下降。\\",\\n      \\"suggestion\\": \\"建议减少关联表数量，拆分查询或对关联字段添加索引以优化性能。\\"\\n    },\\n    {\\n      \\"title\\": \\"多表关联查询超过2张表\\",\\n      \\"severity\\": \\"MEDIUM\\",\\n      \\"startLine\\": 63,\\n      \\"endLine\\": 95,\\n      \\"evidence\\": \\"from company_admin as ca\\\\n        LEFT JOIN other_platform_corp AS opc ON ca.tenant_id = opc.tenant_id\\\\n        LEFT JOIN platform_application as pa on pa.system_code = ca.system_code\\",\\n      \\"description\\": \\"selectErpCompanyList 查询关联了 company_admin、other_platform_corp、platform_application 共3张表，超过2张表的上限，可能造成查询性能下降。\\",\\n      \\"suggestion\\": \\"建议减少关联表数量，拆分查询或对关联字段添加索引以优化性能。\\"\\n    }\\n  ]\\n}","reasoning_content":"我们根据规则，需要检查SQL文件是否包含多表联查（关联查询>2张表）。文件中有两个select语句：selectCompanyAdminList和selectErpCompanyList。它们都从company_admin as ca开始，LEFT JOIN other_platform_corp