ntent":"【检查规则】\\n查询项目文件，找到多表联查的sql，判断这些sql文件是否关联查询大于2张表的\\n\\n【文件】X001-userpermissions/src/main/resources/logback-spring.xml\\n【说明】以下代码每一行格式为 \\"行号|原文\\"；issues 的 startLine/endLine 必须严格对应左侧行号，禁止估算。\\n```xml\\n1|<?xml version=\\"1.0\\" encoding=\\"UTF-8\\"?>\\n2|<configuration  scan=\\"true\\" scanPeriod=\\"60 seconds\\" debug=\\"false\\">\\n3|    <include resource=\\"org/springframework/boot/logging/logback/defaults.xml\\"/>\\n4|\\n5|    <contextName>my_logback</contextName>\\n6|\\n7|    <springProperty name=\\"applicationName\\" scope=\\"context\\" source=\\"spring.application.name\\"/>\\n8|\\n9|    <!-- 规范：单条日志≤4096 字节，消息部分截断 -->\\n10|    <conversionRule conversionWord=\\"msgTruncate\\" converterClass=\\"xyy.base.logging.TruncateMessageConverter\\"/>\\n11|\\n12|    <!-- 规范 1.2.1：生产路径可配置；开发默认 D:/logs/xyy/${applicationName} -->\\n13|    <springProperty name=\\"LOG_FILE_PATH\\" source=\\"logging.file.path\\" defaultValue=\\"D:/logs/xyy/${applicationName}\\"/>\\n14|\\n15|    <!-- 与 userserver / log_content.md 一致：timestamp | 线程 | 日志级别 | SOFA-TraceId | logger | 消息 -->\\n16|    <property name=\\"CONSOLE_LOG_PATTERN\\"\\n17|              value=\\"%d{yyyy-MM-dd HH:mm:ss.SSS}|%-5level|[%15.15t]|SOFA-TraceId=%X{SOFA-TraceId:-}|%logger{40}|%msgTruncate%n%wEx\\"/>\\n18|    <property name=\\"FILE_LOG_PATTERN\\"\\n19|              value=\\"%d{yyyy-MM-dd HH:mm:ss.SSS}|%-5level|%-15t|SOFA-TraceId=%X{SOFA-TraceId:-}|%X{local-ip:-}|%X{last-ip:-}|%X{app-name:-}|%X{cost-time:-}|%logger{50}|%msgTruncate%n%wEx\\"/>\\n20|\\n21|    <!-- Appender to log to console（含 SOFA-TraceId） -->\\n22|    <appender name=\\"console\\" class=\\"ch.qos.logback.core.ConsoleAppender\\">\\n23|        <filter class=\\"ch.qos.logback.classic.filter.ThresholdFilter\\">\\n24|            <level>DEBUG</level>\\n25|        </filter>\\n26|        <encoder>\\n27|            <pattern>${CONSOLE_LOG_PATTERN}</pattern>\\n28|            <charset>utf8</charset>\\n29|        </encoder>\\n30|    </appender>\\n31|\\n32|    <!-- Appender to log to file -->​\\n33|    <appender name=\\"allLog\\" class=\\"ch.qos.logback.core.rolling.RollingFileAppender\\">\\n34|        <rollingPolicy class=\\"ch.qos.logback.core.rolling.TimeBasedRollingPolicy\\">\\n35|            <!--日志文件输出的文件名-->\\n36|            <FileNamePattern>${LOG_FILE_PATH}/%d{yyyy-MM-dd}.all.log.log</FileNamePattern>\\n37|            <!--日志文件保留天数-->\\n38|            <MaxHistory>30</MaxHistory>\\n39|            <!-- 必须加这个回滚才会起作用 -->\\n40|            <CleanHistoryOnStart>true</CleanHistoryOnStart>\\n41|        </rollingPolicy>\\n42|        <encoder class=\\"ch.qos.logback.classic.encoder.PatternLayoutEncoder\\">\\n43|            <pattern>${FILE_LOG_PATTERN}</pattern>\\n44|            <charset>UTF-8</charset>\\n45|        </encoder>\\n46|    </appender>\\n47|\\n48|    <!--异步到文件-->\\n49|    <appender name=\\"asyncAllAppender\\" class=\\"ch.qos.logback.classic.AsyncAppender\\">\\n50|        <!-- 不丢失日志.默认的,如果队列的80%已满,则会丢弃TRACT、DEBUG、INFO级别的日志 -->\\n51|        <discardingThreshold>0</discardingThreshold>\\n52|        <!-- 更改默认的队列的深度,该值会影响性能.默认值为256 -->\\n53|        <queueSize>512</queueSize>\\n54|        <!-- 添加附加的appender,最多只能添加一个 -->\\n55|        <appender-ref ref=\\"allLog\\"/>\\n56|    </appender>\\n57|\\n58|    <!-- Appender to log to file -->​\\n59|    <appender name=\\"infoLog\\" class=\\"ch.qos.logback.core.rolling.RollingFileAppender\\">\\n60|        <rollingPolicy class=\\"ch.qos.logback.core.rolling.TimeBasedRollingPolicy\\">\\n61|            <!--日志文件输出的文件名-->\\n62|            <FileNamePattern>${LOG_FILE_PATH}/%d{yyyy-MM-dd}.info.log.log</FileNamePattern>\\n63|            <!--日志文件保留天数-->\\n64|            <MaxHistory>30</MaxHistory>\\n65|        </rollingPolicy>\\n66|        <!--这里设置日志级别为info-->\\n67|        <filter class=\\"ch.qos.logback.classic.filter.LevelFilter\\">\\n68|            <level>info</level>\\n69|            <onMatch>ACCEPT</onMatch>\\n70|            <onMismatch>DENY</onMismatch>\\n71|        </filter>\\n72|        <encoder class=\\"ch.qos.logback.classic.encoder.PatternLayoutEncoder\\">\\n73|            <pattern>${FILE_LOG_PATTERN}</pattern>\\n74|            <charset>UTF-8</charset>\\n75|        </encoder>\\n76|        <!--日志文件最大的大小-->\\n77|        <triggeringPolicy class=\\"ch.qos.logback.core.rolling.SizeBasedTriggeringPolicy\\">\\n78|            <MaxFileSize>20MB</MaxFileSize>\\n79|        </triggeringPolicy>\\n80|    </appender>\\n81|\\n82|    <!--异步到文件-->\\n83|    <appender name=\\"asyncInfoAppender\\" class=\\"ch.qos.logback.classic.AsyncAppender\\">\\n84|        <!-- 不丢失日志.默认的,如果队列的80%已满,则会丢弃TRACT、DEBUG、INFO级别的日志 -->\\n85|        <discardingThreshold>0</discardingThreshold>\\n86|        <!-- 更改默认的队列的深度,该值会影响性能.默认值为256 -->\\n87|        <queueSize>512</queueSize>\\n88|        <!-- 添加附加的appender,最多只能添加一个 -->\\n89|        <appender-ref ref=\\"infoLog\\"/>\\n90|    </appender>\\n91|\\n92|    <!--新增加的error appender-->\\n93|    <appender name=\\"errorLog\\"  class=\\"ch.qos.logback.core.rolling.RollingFileAppender\\">\\n94|        <rollingPolicy class=\\"ch.qos.logback.core.rolling.TimeBasedRollingPolicy\\">\\n95|            <!--日志文件输出的文件名-->\\n96|            <FileNamePattern>${LOG_FILE_PATH}/%d{yyyy-MM-dd}.error.log.log</FileNamePattern>\\n97|            <!--日志文件保留天数-->\\n98|            <MaxHistory>30</MaxHistory>\\n99|        </rollingPolicy>\\n100|        <!--这里设置日志级别为error-->\\n101|        <filter class=\\"ch.qos.logback.classic.filter.LevelFilter\\">\\n102|            <level>error</level>\\n103|            <onMatch>ACCEPT</onMatch>\\n104|            <onMismatch>DENY</onMismatch>\\n105|        </filter>\\n106|        <encoder class=\\"ch.qos.logback.classic.encoder.PatternLayoutEncoder\\">\\n107|            <pattern>${FILE_LOG_PATTERN}</pattern>\\n108|            <charset>UTF-8</charset>\\n109|        </encoder>\\n110|        <!--日志文件最大的大小-->\\n111|        <triggeringPolicy class=\\"ch.qos.logback.core.rolling.SizeBasedTriggeringPolicy\\">\\n112|            <MaxFileSize>20MB</MaxFileSize>\\n113|        </triggeringPolicy>\\n114|    </appender>\\n115|\\n116|    <appender name=\\"asyncErrorAppender\\" class=\\"ch.qos.logback.classic.AsyncAppender\\">\\n117|        <!-- 不丢失日志.默认的,如果队列的80%已满,则会丢弃TRACT、DEBUG、INFO级别的日志 -->\\n118|        <discardingThreshold>0</discardingThreshold>\\n119|        <!-- 更改默认的队列的深度,该值会影响性能.默认值为256 -->\\n120|        <queueSize>512</queueSize>\\n121|        <!-- 添加附加的appender,最多只能添加一个 -->\\n122|        <appender-ref ref=\\"errorLog\\"/>\\n123|    </appender>\\n124|    ​\\n125|    <!-- Appender to log to file in a JSON format -->\\n126|    <appender name=\\"logStash\\" class=\\"ch.qos.logback.core.rolling.RollingFileAppender\\">\\n127|        <rollingPolicy class=\\"ch.qos.logback.core.rolling.TimeBasedRollingPolicy\\">\\n128|            <fileNamePattern>${LOG_FILE_PATH}/%d{yyyy-MM-dd}.json.log</fileNamePattern>\\n129|            <maxHistory>30</maxHistory>\\n130|        </rollingPolicy>\\n131|        <encoder class=\\"net.logstash.logback.encoder.LoggingEventCompositeJsonEncoder\\">\\n132|            <providers>\\n133|                <timestamp>\\n134|                    <timeZone>UTC</timeZone>\\n135|                </timestamp>\\n136|                <pattern>\\n137|                    <pattern>\\n138|                        {\\n139|                        \\"severity\\": \\"%level\\",\\n140|                        \\"service\\": \\"${applicationName:-}\\",\\n141|                        \\"SOFA-TraceId\\": \\"%X{SOFA-TraceId:-}\\",\\n142|                        \\"pid\\": \\"${PID:-}\\",\\n143|                        \\"thread\\": \\"%thread\\",\\n144|                        \\"class\\": \\"%logger{40}\\",\\n145|                        \\"rest\\": \\"%message\\"\\n146|                        }\\n147|                    </pattern>\\n148|                </pattern>\\n149|            </providers>\\n150|        </encoder>\\n151|    </appender>\\n152|\\n153|    <root level=\\"info\\">\\n154|        <appender-ref ref