n>\\n108|            <charset>UTF-8</charset>\\n109|        </encoder>\\n110|        <!--日志文件最大的大小-->\\n111|        <triggeringPolicy class=\\"ch.qos.logback.core.rolling.SizeBasedTriggeringPolicy\\">\\n112|            <MaxFileSize>20MB</MaxFileSize>\\n113|        </triggeringPolicy>\\n114|    </appender>\\n115|\\n116|    <appender name=\\"asyncErrorAppender\\" class=\\"ch.qos.logback.classic.AsyncAppender\\">\\n117|        <!-- 不丢失日志.默认的,如果队列的80%已满,则会丢弃TRACT、DEBUG、INFO级别的日志 -->\\n118|        <discardingThreshold>0</discardingThreshold>\\n119|        <!-- 更改默认的队列的深度,该值会影响性能.默认值为256 -->\\n120|        <queueSize>512</queueSize>\\n121|        <!-- 添加附加的appender,最多只能添加一个 -->\\n122|        <appender-ref ref=\\"errorLog\\"/>\\n123|    </appender>\\n124|    ​\\n125|    <!-- Appender to log to file in a JSON format -->\\n126|    <appender name=\\"logStash\\" class=\\"ch.qos.logback.core.rolling.RollingFileAppender\\">\\n127|        <rollingPolicy class=\\"ch.qos.logback.core.rolling.TimeBasedRollingPolicy\\">\\n128|            <fileNamePattern>${LOG_FILE_PATH}/%d{yyyy-MM-dd}.json.log</fileNamePattern>\\n129|            <maxHistory>30</maxHistory>\\n130|        </rollingPolicy>\\n131|        <encoder class=\\"net.logstash.logback.encoder.LoggingEventCompositeJsonEncoder\\">\\n132|            <providers>\\n133|                <timestamp>\\n134|                    <timeZone>UTC</timeZone>\\n135|                </timestamp>\\n136|                <pattern>\\n137|                    <pattern>\\n138|                        {\\n139|                        \\"severity\\": \\"%level\\",\\n140|                        \\"service\\": \\"${applicationName:-}\\",\\n141|                        \\"SOFA-TraceId\\": \\"%X{SOFA-TraceId:-}\\",\\n142|                        \\"pid\\": \\"${PID:-}\\",\\n143|                        \\"thread\\": \\"%thread\\",\\n144|                        \\"class\\": \\"%logger{40}\\",\\n145|                        \\"rest\\": \\"%message\\"\\n146|              