ult column=\\"endTime\\" jdbcType=\\"VARCHAR\\" property=\\"endTime\\" />\\n24|    <result column=\\"channel\\" jdbcType=\\"VARCHAR\\" property=\\"channel\\" />\\n25|\\n26|\\n27|  </resultMap>\\n28|  <sql id=\\"Base_Column_List\\">\\n29|    id, account, admin_name, company_name, company_code, tenant_id, tenant_photo, create_time, \\n30|    update_time, status,be_logoff, system_code, email, corp_province, corp_city\\n31|  </sql>\\n32|  <select id=\\"selectCompanyAdminList\\" resultMap=\\"BaseResultMap\\">\\n33|      SELECT\\n34|      <include refid=\\"Base_Column_List\\"/>,\\n35|      opc.start_time as startTime,\\n36|      opc.end_time as endTime,\\n37|      pa.system_name as systemName,\\n38|      opc.channel as channel\\n39|      FROM company_admin AS ca\\n40|      LEFT JOIN other_platform_corp AS opc ON ca.tenant_id = opc.tenant_id\\n41|      LEFT JOIN platform_application AS pa ON pa.system_code = ca.system_code\\n42|      <where>\\n43|          1 = 1 and be_logoff=1\\n44|          <if test=\\"startMinTime != null and startMinTime != ''''\\">and opc.start_time &gt;= #{startMinTime}</if>\\n45|          <if test=\\"startMaxTime != null and startMaxTime != ''''\\">and opc.start_time &lt;= #{startMaxTime}</if>\\n46|          <if test=\\"endMinTime != null and endMinTime != ''''\\">and opc.end_time &gt;= #{endMinTime}</if>\\n47|          <if test=\\"endMaxTime != null and endMaxTime != ''''\\">and opc.end_time &lt;= #{endMaxTime}</if>\\n48|          <if test=\\"tenantId != null and tenantId != ''''\\">and ca.tenant_id like concat(#{tenantId},''%'')</if>\\n49|          <if test=\\"companyName != null and companyName != ''''\\">and ca.company_name like concat(#{companyName},''%'')</if>\\n50|          <if test=\\"systemName != null and systemName != ''''\\">and pa.system_name like concat(#{systemName},''%'')</if>\\n51|          <if test=\\"status != null and status != ''''\\">and ca.status = #{status}</if>\\n52|          <if test=\\"systemCodeList.size() != 0 and systemCodeList!= null\\">\\n53|            and ca.system_code in\\n54|            <foreach collection=\\"systemCodeList\\" open=\\"(\\" separator=\\",\\" close=\\")\\" item=\\"item\\">\\n55|                #{item}\\n56|            </foreach>\\n57|          </if>\\n58|      </where>\\n59|\\n60|      ORDER BY ca.create_time DESC\\n61|  </select>\\n62|\\n63|    <select id=\\"selectErpCompanyList\\" resultMap=\\"BaseResultMap\\">\\n64|        select\\n65|        <include refid=\\"Base_Column_List\\"/>,\\n66|        pa.system_name,\\n67|        opc.channel as channel\\n68|        from company_admin as ca\\n69|        LEFT JOIN other_platform_corp AS opc ON ca.tenant_id = opc.tenant_id\\n70|        LEFT JOIN platform_application as pa on pa.system_code = ca.system_code\\n71|        <where>\\n72|            1 = 1  and be_logoff=1\\n73|            <if test=\\"companyName != null and companyName != ''''\\">and ca.company_name like concat(#{companyName},''%'') </if>\\n74|            <if test=\\"tenantId != null and tenantId != ''''\\">and ca.tenant_id like concat(#{tenantId},''%'')</if>\\n75|            <if test=\\"userName != null and userName != ''''\\">and ca.admin_name like concat(#{userName},''%'')</if>\\n76|            <if test=\\"userCode != null and userCode != ''''\\">and ca.account like concat(#{userCode},''%'')</if>\\n77|            <if test=\\"province != null and province != ''''\\">and ca.corp_province like concat(#{province},''%'')</if>\\n78|            <if test=\\"city != null and city != ''''\\">and ca.corp_city like concat(#{city},''%'')</if>\\n79|            <if test=\\"startTime != null and startTime != ''''\\">and ca.create_time &gt;= #{startTime}</if>\\n80|            <if test=\\"endTime != null and endTime != ''''\\">and ca.create_time &lt;= #{endTime}</if>\\n81|            <if test=\\"systemCodeList.size() != 0 and systemCodeList!= null\\">\\n82|                and pa.system_code in\\n83|                <foreach\\n84|                        collection=\\"sys