ons/src/main/resources/mapper/OtherPlatformCorpMapper.xml\\n【说明】以下代码每一行格式为 \\"行号|原文\\"；issues 的 startLine/endLine 必须严格对应左侧行号，禁止估算。\\n```xml\\n1|<?xml version=\\"1.0\\" encoding=\\"UTF-8\\"?>\\n2|<!DOCTYPE mapper PUBLIC \\"-//mybatis.org//DTD Mapper 3.0//EN\\" \\"http://mybatis.org/dtd/mybatis-3-mapper.dtd\\">\\n3|<mapper namespace=\\"xyy.base.mapper.OtherPlatformCorpMapper\\">\\n4|  <resultMap id=\\"BaseResultMap\\" type=\\"xyy.base.entity.OtherPlatformCorpEntity\\">\\n5|    <id column=\\"id\\" jdbcType=\\"INTEGER\\" property=\\"id\\" />\\n6|    <result column=\\"system_code\\" jdbcType=\\"VARCHAR\\" property=\\"systemCode\\" />\\n7|    <result column=\\"corp_id\\" jdbcType=\\"VARCHAR\\" property=\\"corpId\\" />\\n8|    <result column=\\"tenant_id\\" jdbcType=\\"VARCHAR\\" property=\\"tenantId\\" />\\n9|    <result column=\\"corp_name\\" jdbcType=\\"VARCHAR\\" property=\\"corpName\\" />\\n10|    <result column=\\"corp_province\\" jdbcType=\\"VARCHAR\\" property=\\"corpProvince\\" />\\n11|    <result column=\\"corp_city\\" jdbcType=\\"VARCHAR\\" property=\\"corpCity\\" />\\n12|    <result column=\\"user_id\\" jdbcType=\\"VARCHAR\\" property=\\"userId\\" />\\n13|    <result column=\\"auth_state\\" jdbcType=\\"BIT\\" property=\\"authState\\" />\\n14|    <result column=\\"create_time\\" jdbcType=\\"TIMESTAMP\\" property=\\"createTime\\" />\\n15|    <result column=\\"admin_account\\" jdbcType=\\"VARCHAR\\" property=\\"adminAccount\\" />\\n16|    <result column=\\"package_standard_id\\" jdbcType=\\"INTEGER\\" property=\\"packageStandardId\\" />\\n17|    <result column=\\"start_time\\" jdbcType=\\"TIMESTAMP\\" property=\\"startTime\\" />\\n18|    <result column=\\"end_time\\" jdbcType=\\"TIMESTAMP\\" property=\\"endTime\\" />\\n19|\\n20|\\n21|    <result column=\\"platformName\\" jdbcType=\\"VARCHAR\\" property=\\"platformName\\" />\\n22|  </resultMap>\\n23|  <sql id=\\"Base_Column_List\\">\\n24|    id, system_code, corp_id, tenant_id, corp_name, corp_province, corp_city, user_id, \\n25|    auth_state, create_time, admin_account, package_standard_id, start_time, end_time\\n26|  </sql>\\n27|  <select id=\\"selectByTenantId\\" resultMap=\\"BaseResultMap\\">\\n28|      SELECT\\n29|      opc.tenant_id, pi.platform_name as platformName\\n30|      FROM other_platform_corp as opc\\n31|      LEFT JOIN platform_standard as ps on ps.id = opc.package_standard_id\\n32|      LEFT JOIN platform_identification as pi on pi.platform_sign = ps.platform_sign\\n33|      <where>\\n34|          opc.tenant_id in\\n35|          <foreach collection=\\"tenantIds\\" open=\\"(\\" separator=\\",\\" close=\\")\\" item=\\"item\\">#{item}</foreach>\\n36|      </where>\\n37|  </select>\\n38|\\n39|    <select id=\\"selectByTenantIds\\" resultMap=\\"BaseResultMap\\">\\n40|        SELECT\\n41|        opc.tenant_id,opc.system_code, pi.platform_name as platformName\\n42|        FROM other_platform_corp as opc\\n43|        LEFT JOIN platform_standard as ps on ps.id = opc.package_standard_id\\n44|        LEFT JOIN platform_identification as pi on pi.platform_sign = ps.platform_sign\\n45|        <where>\\n46|            opc.tenant_id in\\n47|            <foreach collection=\\"tenantIds\\" open=\\"(\\" separator=\\",\\" close=\\")\\" item=\\"item\\">#{item}</foreach>\\n48|        </where>\\n49|    </select>\\n50|  <select id=\\"selectByPlatformName\\" resultMap=\\"BaseResultMap\\">\\n51|      SELECT\\n52|      opc.tenant_id, pi.platform_name as platformName\\n53|      FROM other_platform_corp as opc\\n54|      LEFT JOIN platform_standard as ps on ps.id = opc.package_standard_id\\n55|      LEFT JOIN platform_identification as pi on pi.platform_sign = ps.platform_sign\\n56|      <where>\\n57|          pi.platform_name like concat(#{source},''%'')\\n58|      </where>\\n59|  </select>\\n60|  <select id=\\"selectByPackageStandardId\\" resultMap=\\"BaseResultMap\\">\\n61|      SELECT opc.tenant_id, pi.platform_name as platformName\\n62|      FROM other_platform_corp as opc\\n63|  