】\\n扫描代码文件，看看哪些js方法没有被调用过\\n\\n【文件】herolord9_disco-elysium-blog-front/scripts/compress-image.js\\n【说明】以下代码每一行格式为 \\"行号|原文\\"；issues 的 startLine/endLine 必须严格对应左侧行号，禁止估算。\\n```javascript\\n1|#!/usr/bin/env node\\n2|/**\\n3| * 免费图片压缩脚本（使用 Node.js）\\n4| * 使用方法: node scripts/compress-image.js\\n5| * \\n6| * 需要先安装: pnpm add -D sharp\\n7| */\\n8|\\n9|const fs = require(''fs'')\\n10|const path = require(''path'')\\n11|\\n12|// 检查是否安装了 sharp\\n13|let sharp\\n14|try {\\n15|  sharp = require(''sharp'')\\n16|} catch (e) {\\n17|  console.error(''❌ 未安装 sharp 库'')\\n18|  console.log(''请先安装: pnpm add -D sharp'')\\n19|  process.exit(1)\\n20|}\\n21|\\n22|const IMAGE_FILE = path.join(__dirname, ''../public/login-bg.png'')\\n23|const OUTPUT_WEBP = path.join(__dirname, ''../public/login-bg.webp'')\\n24|const OUTPUT_COMPRESSED = path.join(__dirname, ''../public/login-bg-compressed.png'')\\n25|\\n26|async function compressImage() {\\n27|  console.log(''============================================'')\\n28|  console.log(''图片压缩工具（免费）'')\\n29|  console.log(''============================================'')\\n30|  console.log('''')\\n31|\\n32|  // 检查文件是否存在\\n33|  if (!fs.existsSync(IMAGE_FILE)) {\\n34|    console.error(`❌ 文件不存在: ${IMAGE_FILE}`)\\n35|    process.exit(1)\\n36|  }\\n37|\\n38|  // 获取原始文件大小\\n39|  const originalStats = fs.statSync(IMAGE_FILE)\\n40|  const originalSize = (originalStats.size / 1024 / 1024).toFixed(2)\\n41|  console.log(`📁 原始文件: ${IMAGE_FILE}`)\\n42|  console.log(`📊 原始大小: ${originalSize} MB`)\\n43|  console.log('''')\\n44|\\n45|  try {\\n46|    // 方案 1: 转换为 WebP（推荐）\\n47|    console.log(''🔄 正在转换为 WebP 格式...'')\\n48|    await sharp(IMAGE_FILE)\\n49|      .webp({ quality: 80 })\\n50|      .toFile(OUTPUT_WEBP)\\n51|    \\n52|    const webpStats = fs.statSync(OUTPUT_WEBP)\\n53|    const webpSize = (webpStats.size / 1024 / 1024).toFixed(2)\\n54|    const webpReduction = ((1 - webpStats.size / originalStats.size) * 100).toFixed(1)\\n55|    \\n56|    console.log(`✅ WebP 文件已生成: ${OUTPUT_WEBP}`)\\n57|    console.log(`📊 WebP 大小: ${webpSize} MB (减少 ${webpReduction}%)`)\\n58|    console.log('''')\\n59|\\n60|    // 方案 2: 压缩 PNG\\n61|    console.log(''🔄 正在压缩 PNG 格式...'')\\n62|    await sharp(IMAGE_FILE)\\n63|      .png({ quality: 80, compressionLevel: 9 })\\n64|      .resize(1920, 1080, { \\n65|        fit: ''inside'',\\n66|        withoutEnlargement: true \\n67|      })\\n68|      .toFile(OUTPUT_COMPRESSED)\\n69|    \\n70|    const compressedStats = fs.statSync(OUTPUT_COMPRESSED)\\n71|    const compressedSize = (compressedStats.size / 1024 / 1024).toFixed(2)\\n72|    const compressedReduction = ((1 - compressedStats.size / originalStats.size) * 100).toFixed(1)\\n73|    \\n74|    console.log(`✅ 压缩 PNG 已生成: ${OUTPUT_COMPRESSED}`)\\n75|    console.log(`📊 压缩 PNG 大小: ${compressedSize} MB (减少 ${compressedReduction}%)`)\\n76|    console.log('''')\\n77|\\n78|    console.log(''============================================'')\\n79|    console.log(''✅ 压缩完成！'')\\n80|    console.log(''============================================'')\\n81|    console.log('''')\\n82|    console.log(''📝 下一步：'')\\n83|    console.log('''')\\n84|    console.log(''方案 A - 使用 WebP（推荐，文件最小）：'')\\n85|    console.log(''  1. 修改 src/pages/Login.tsx 第 70 行：'')\\n86|    console.log(''     backgroundImage: \\\\''url(/login-bg.webp)\\\\'','')\\n87|    console.log(''  2. 重新构建: pnpm build'')\\n88|    console.log('''')\\n89|    console.log(''方案 B - 使用压缩 PNG（兼容性好）：'')\\n90|    console.log(''  1. 替换文件: mv public/login-bg-compressed.png public/login-bg.png'')\\n91|    console.log(''  2. 重新构建: pnpm build'')\\n92|    console.log('''')\\n93|    console.log(''方案 C - 同时使用（最佳）：'')\\n94|    console.log(''  1. 保留 WebP 和压缩 PNG'')\\n95|    console.log(''  2. 修改代码支持格式回退'')\\n96|    console.log('''')\\n97|\\n98|  } catch (error) {\\n99|    console.error(''❌ 压缩失败:'', error.message)\\n100|    process.exit(1)\\n101|  }\\n102|}\\n103|\\n104|compressImage()\\n105|\\n106|\\n```"}],"temperature":0,"response_format":