\\":\\"整改建议必须用中文\\"}]}"},{"role":"user","content":"【检查规则】\\n扫描代码文件，看看哪些js方法没有被调用过\\n\\n【结果更新/整理要求】\\n记录文件名称，方法名称，和行号\\n\\n【文件】herolord9_disco-elysium-website/src/views/ArticleDetail.vue\\n【说明】以下代码每一行格式为 \\"行号|原文\\"；issues 的 startLine/endLine 必须严格对应左侧行号，禁止估算。\\n```vue\\n1|<template>\\n2|  <div class=\\"article-detail-page\\">\\n3|    <Header />\\n4|    <main class=\\"main-content\\">\\n5|      <div class=\\"container\\">\\n6|        <div v-if=\\"loading\\" class=\\"loading\\">加载中...</div>\\n7|        <div v-else-if=\\"error\\" class=\\"error\\">{{ error }}</div>\\n8|        <div v-else-if=\\"articleData\\" class=\\"article-wrapper\\">\\n9|          <div class=\\"article-layout\\">\\n10|            <div class=\\"article-content\\">\\n11|              <div class=\\"article-header\\">\\n12|                <div v-if=\\"articleData.article.type === ''file''\\" class=\\"category-tag\\">\\n13|                  {{ getCategoryFromPath(articleData.article.sourcePath) }}\\n14|                </div>\\n15|                <h1 class=\\"article-title\\">{{ articleData.article.title }}</h1>\\n16|                <div class=\\"article-meta\\">\\n17|                  <span v-if=\\"articleData.article.publishedTime\\">\\n18|                    {{ formatDate(articleData.article.publishedTime) }}\\n19|                  </span>\\n20|                  <span v-if=\\"articleData.article.author\\"> • {{ articleData.article.author }}</span>\\n21|                </div>\\n22|              </div>\\n23|              \\n24|              <div\\n25|                v-if=\\"articleData.content\\"\\n26|                class=\\"article-body markdown-body\\"\\n27|                v-html=\\"renderedContent\\"\\n28|                ref=\\"markdownContent\\"\\n29|              ></div>\\n30|            </div>\\n31|            \\n32|            <!-- 目录侧边栏 -->\\n33|            <aside v-if=\\"tocItems.length > 0\\" class=\\"toc-sidebar\\" :class=\\"{ ''mobile-hidden'': !isTocOpen }\\">\\n34|              <div class=\\"toc-container\\">\\n35|                <div class=\\"toc-header\\">\\n36|                  目录\\n37|                  <button class=\\"close-toc-btn\\" @click=\\"isTocOpen = false\\" aria-label=\\"关闭目录\\">✕</button>\\n38|                </div>\\n39|                <nav class=\\"toc-nav\\">\\n40|                  <ul class=\\"toc-list\\">\\n41|                    <li\\n42|                      v-for=\\"item in tocItems\\"\\n43|                      :key=\\"item.id\\"\\n44|                      :class=\\"[''toc-item'', `toc-level-${item.level}`, { active: activeTocId === item.id }]\\"\\n45|                    >\\n46|                      <a\\n47|                        :href=\\"`#${item.id}`\\"\\n48|                        @click.prevent=\\"scrollToHeading(item.id)\\"\\n49|                        class=\\"toc-link\\"\\n50|                      >\\n51|                        {{ item.text }}\\n52|                      </a>\\n53|                    </li>\\n54|                  </ul>\\n55|                </nav>\\n56|              </div>\\n57|            </aside>\\n58|          </div>\\n59|          \\n60|          <!-- 移动端目录开关按钮 -->\\n61|          <button v-if=\\"tocItems.length > 0\\" class=\\"mobile-toc-toggle\\" @click=\\"isTocOpen = true\\" aria-label=\\"打开目录\\">\\n62|            📑 目录\\n63|          </button>\\n64|\\n65|          <!-- 图片预览模态框 -->\\n66|          <div v-if=\\"previewImage\\" class=\\"image-preview-modal\\" @click=\\"closePreview\\">\\n67|            <div class=\\"image-preview-content\\" @click.stop>\\n68|              <button class=\\"image-preview-close\\" @click=\\"closePreview\\">×</button>\\n69|              <img :src=\\"previewImage\\" alt=\\"预览图片\\" class=\\"preview-image\\" />\\n70|            </div>\\n71|          </div>\\n72|        </div>\\n73|      </div>\\n74|    </main>\\n75|    <Footer />\\n76|  </div>\\n77|</template>\\n78|\\n79|<script setup lang=\\"ts\\">\\n80|import { ref, onMounted, onUnmounted, nextTick, watch } from ''vue''\\n81|import { useRoute, useRouter } from ''vue-router''\\n82|import { marked } from ''marked''\\n83|import { useTheme } from ''@/composables/useTheme''\\n84|import { blogApi } from ''@/services/blog''\\n85|import { API_BASE_URL } from ''@/utils/api''\\n86|import type { BlogArticle, BlogArticleContent } from ''@/types/blog''\\n87|import Header from ''@/components/Header.vue''\\n88|import Footer from ''@/components/Footer.vue''\\n89|\\n90|const route = useRoute()\\n91|const router = useRouter()\\n92|const { initTheme } = useTheme()\\n93|\\n94|const articleData = ref<{ article: BlogArticle; content?: BlogArticleContent } | null>(null)\\n95|const loading = ref(false)\\n96|const error = ref<string | null>(null)\\n97|const markdownContent = ref<HTMLElement | null>(null)\\n98|const previewImage = ref<string | null>(null)\\n99|const renderedContent = ref<string>('''')\\n100|const activeTocId = ref<string>('''')\\n101|const isTocOpen = ref(false)\\n102|\\n103|// 滚动监听器引用，用于清理\\n104|let scrollHandler: (() => void) | null = null\\n105|let scrollTimeout: number | null = null\\n106|let rafId: number | null = null\\n107|let ticking = false\\n108|\\n109|// 目录项类型\\n110|interface TocItem {\\n111|  id: string\\n112|  text: string\\n113|  level: number\\n114|}\\n115|\\n116|const tocItems = ref<TocItem[]>([])\\n117|\\n118|/**\\n119| * 生成标题 ID（用于锚点）\\n120| */\\n121|const generateHeadingId = (text: string): string => {\\n122|  return text\\n123|    .toLowerCase()\\n124|    .replace(/[^\\\\w\\\\u4e00-\\\\u9fa5]+/g, ''-'')\\n125|    .replace(/^-+|-+$/g, '''')\\n126|}\\n127|\\n128|/**\\n129| * 修复代码块内的标题 - 将它们转换为普通文本\\n130| * 使用DOM解析方法更可靠地处理嵌套情况\\n131| */\\n132|const fixHeadingsInCodeBlocks = (html: string): string => {\\n133|  // 在浏览器环境中使用DOM解析\\n134|  if (typeof document === ''undefined'') {\\n135|    // 如果不在浏览器环境，使用正则表达式（降级方案）\\n136|    return html.replace(/(<(?:pre|code)[^>]*>)([\\\\s\\\\S]*?)(<\\\\/(?:pre|code)>)/gi, (_match, openTag, content, closeTag) => {\\n137|      // 移除代码块内的所有标题标签，保留文本内容\\n138|      const fixedContent = content.replace(/<h[1-6][^>]*>([\\\\s\\\\S]*?)<\\\\/h[1-6]>/gi, (_headingMatch: string, innerContent: string) => {\\n139|        // 提取文本内容（移除所有HTML标签）\\n140|        const textOnly = innerContent.replace(/<[^>]+>/g, '''').trim()\\n141|        return textOnly || ''''\\n142|      })\\n143|      return openTag + fixedContent + closeTag\\n144|    })\\n145|  }\\n146|  \\n147|  // 使用DOM解析（更可靠）\\n148|  const tempDiv = document.createElement(''div'')\\n149|  tempDiv.innerHTML = html\\n150|  \\n151|  // 查找所有代码块（包括嵌套在p标签内的code）\\n152|  const codeElements = tempDiv.querySelectorAll(''pre, code, p > code'')\\n153|  \\n154|  codeElements.forEach((codeElement) => {\\n155|    // 在代码块内查找所有标题\\n156|    const headings = codeElement.querySelectorAll(''h1, h2, h3, h4, h5, h6'')\\n157|    headings.forEach((heading) => {\\n158|      // 提取文本内容（包括所有子元素的文本）\\n159|      const textContent = heading.textContent || ''''\\n160|      // 创建文本节点替换标题\\n161|      const textNode = document.createTextNode(textContent.trim())\\n162|      heading.parentNode?.replaceChild(textNode, heading)\\n163|    })\\n164|  })\\n165|  \\n166|  return tempDiv.innerHTML\\n167|}\\n168|\\n169|/**\\n170| * 解析 HTML 中的标题并生成目录\\n171| */\\n172|const parseToc = (html: string): { html: string; toc: TocItem[] } => {\\n173|  const toc: TocItem[] = []\\n174|  let tocIndex = 0\\n175|  \\n176|  // 先修复代码块内的标题\\n177|  let processedHtml = fixHeadingsInCodeBlocks(html)\\n178|  \\n179|  // 使用DOM解析来更准确地识别标题位置\\n180|  if (typeof document !== ''undefined'') {\\n181|    const tempDiv = document.createElement(''div'')\\n182|    tempDiv.innerHTML = processedHtml\\n183|    \\n184|    // 查找所有标题\\n185|    const headings = tempDiv.querySelectorAll(''h1, h2, h3, h4, h5, h6'')\\n186|    \\n187|    headings.forEach((heading) => {\\n188|      // 检查标题是否在代码块内\\n189|      const isInCodeBlock = heading.closest(''pre, code, p > code'') !== null\\n190|      \\n191|      if (!isInCodeBlock) {\\n192|        const headingLevel = parseInt(heading.tagName.charAt(1))\\n193|        const headingText = heading.textContent?.trim() || ''''\\n194|        const headingId = generateHeadingId(headingText) || `heading-${tocIndex++}`\\n195|        \\n196|        // 设置id\\n197|        heading.id = headingId\\n198|        \\n199|        // 添加到目录\\n200|        toc.push({\\n201|          id: headingId,\\n202|          text: headingText,\\n203|          level: headingLevel\\n204|        })\\n205|      } else {\\n206|        // 如果标题在代码块内，移除它（已经在fixHeadingsInCodeBlocks中处理了）\\n207|        // 这里只是确保它不会被添加到目录\\n208|      }\\n209|    })\\n210|    \\n211|    processedHtml = tempDiv.innerHTML\\n212|  } else {\\n213|    // 降级方案：使用正则表达式\\n214|    processedHtml = processedHtml.replace(/<h([1-6])([^>]*)>([^<]+)<\\\\/h[1-6]>/gi, (_match, level, attrs, text) => {\\n215|      const headingLevel = parseInt(level)\\n216|      const headingText = text.trim()\\n217|      const headingId = generateHeadingId(headingText) || `heading-${tocIndex++}`\\n218|      \\n219|      // 添加到目录\\n220|      toc.push({\\n221|        id: headingId,\\n222|        text: headingText,\\n223|        level: headingLevel\\n224|      })\\n225|      \\n226|      // 返回带 id 的标题标签\\n227|      return `<h${level}${attrs} id=\\"${headingId}\\">${headingText}</h${level}>`\\n228|    })\\n229|  }\\n230|  \\n231|  return { html: processedHtml, toc }\\n232|}\\n233|\\n234|/**\\n235| * 修复段落中的表格 - 将包含表格标记的段落转换为真正的HTML表格\\n236| */\\n237|const fixTablesInParagraphs = (html: string): string => {\\n238|  if (typeof document === ''undefined'') {\\n239|    // 如果不在浏览器环境，使用正则表达式（降级方案）\\n240|    return html.replace(/<p>([\\\\s\\\\S]*?\\\\|[\\\\s\\\\S]*?\\\\|[\\\\s\\\\S]*?\\\\n[\\\\s\\\\S]*?\\\\|[\\\\s\\\\S]*?---[\\\\s\\\\S]*?\\\\|[\\\\s\\\\S]*?\\\\n[\\\\s\\\\S]*?\\\\|[\\\\s\\\\S]*?\\\\|[\\\\s\\\\S]*?)<\\\\/p>/gi, (match, content) => {\\n241|      // 解析表格内容并转换为HTML表格\\n242|      const tableHtml = parseTableFromHtml(content)\\n243|      return tableHtml || match\\n244|    })\\n245|  }\\n246|  \\n247|  // 使用DOM解析（更可靠）\\n248|  const tempDiv = document.createElement(''div'')\\n249|  tempDiv.innerHTML = html\\n250|  \\n251|  // 查找所有段落\\n252|  const paragraphs = tempDiv.querySelectorAll(''p'')\\n253|  \\n254|  paragraphs.forEach((p) => {\\n255|    const innerHTML = p.innerHTML\\n256|    const text = p.textContent || ''''\\n257|    \\n258|    // 检查是否包含表格标记（至少两行，包含|和---）\\n259|    const lines = text.split(''\\\\n'').map(l => l.trim()).filter(l => l)\\n260|    if (lines.length >= 2 && lines.some(line => line.includes(''|'')) && lines.some(line => /---/.test(line))) {\\n261|      // 这是一个表格，转换为HTML表格\\n262|      const tableHtml = parseTableFromHtml(innerHTML)\\n263|      if (tableHtml) {\\n264|        const tableElement = document.createElement(''div'')\\n265|        tableElement.innerHTML = tableHtml\\n266|        const table = tableElement.querySelector(''table'')\\n267|        if (table) {\\n268|          p.parentNode?.replaceChild(table, p)\\n269|        }\\n270|      }\\n271|    }\\n272|  })\\n273|  \\n274|  return tempDiv.innerHTML\\n275|}\\n276|\\n277|/**\\n278| * 从HTML内容中解析表格（可能包含HTML标签）\\n279| */\\n280|const parseTableFromHtml = (htmlContent: string): string => {\\n281|  // 先提取纯文本用于分析结构\\n282|  const tempDiv = typeof document !== ''undefined'' ? document.createElement(''div'') : null\\n283|  if (tempDiv) {\\n284|    tempDiv.innerHTML = htmlContent\\n285|    const text = tempDiv.textContent || ''''\\n286|    const lines = text.split(''\\\\n'').map(l => l.trim()).filter(l => l)\\n287|    \\n288|    if (lines.length < 2) return ''''\\n289|    \\n290|    // 找到分隔行（包含---的行）\\n291|    const separatorIndex = lines.findIndex(line => /^\\\\|[\\\\s\\\\-:]+\\\\|/.test(line))\\n292|    if (separatorIndex === -1 || separatorIndex === 0) return ''''\\n293|    \\n294|    // 重新解析HTML内容以保留格式\\n295|    const htmlLines = htmlContent.split(''\\\\n'').map(l => l.trim()).filter(l => l)\\n296|    const htmlHeaderLine = htmlLines[0] || ''''\\n297|    const htmlHeaders = parseTableRowFromHtml(htmlHeaderLine)\\n298|    \\n299|    const htmlBodyLines = htmlLines.slice(separatorIndex + 1)\\n300|    const htmlRows = htmlBodyLines.map(line => parseTableRowFromHtml(line))\\n301|    \\n302|    // 生成HTML表格\\n303|    let tableHtml = ''<table>\\\\n<thead>\\\\n<tr>''\\n304|    htmlHeaders.forEach(header => {\\n305|      tableHtml += `<th>${header || ''''}</th>`\\n306|    })\\n307|    tableHtml += ''</tr>\\\\n</thead>\\\\n<tbody>''\\n308|    \\n309|    htmlRows.forEach(row => {\\n310|      if (row.length > 0) {\\n311|        tableHtml += ''\\\\n<tr>''\\n312|        row.forEach(cell => {\\n313|          tableHtml += `<td>${cell || ''''}</td>`\\n314|        })\\n315|        tableHtml += ''</tr>''\\n316|      }\\n317|    })\\n318|    \\n319|    tableHtml += ''\\\\n</tbody>\\\\n</table>''\\n320|    return tableHtml\\n321|  }\\n322|  \\n323|  // 降级方案：纯文本解析\\n324|  const lines = htmlContent.split(''\\\\n'').map(l => l.trim()).filter(l => l)\\n325|  if (lines.length < 2) return ''''\\n326|  \\n327|  const separatorIndex = lines.findIndex(line => /^\\\\|[\\\\s\\\\-:]+\\\\|/.test(line))\\n328|  if (separatorIndex === -1 || separatorIndex === 0) return ''''\\n329|  \\n330|  const headers = parseTableRowFromText(lines[0])\\n331|  const rows = lines.slice(separatorIndex + 1).map(line => parseTableRowFromText(line))\\n332|  \\n333|  let tableHtml = ''<table>\\\\n<thead>\\\\n<tr>''\\n334|  headers.forEach(header => {\\n335|    tableHtml += `<th>${escapeHtml(header)}</th>`\\n336|  })\\n337|  tableHtml += ''</tr>\\\\n</thead>\\\\n<tbody>''\\n338|  \\n339|  rows.forEach(row => {\\n340|    if (row.length > 0) {\\n341|      tableHtml += ''\\\\n<tr>''\\n342|      row.forEach(cell => {\\n343|        tableHtml += `<td>${escapeHtml(cell)}</td>`\\n344|      })\\n345|      tableHtml += ''</tr>''\\n346|    }\\n347|  })\\n348|  \\n349|  tableHtml += ''\\\\n</tbody>\\\\n</table>''\\n350|  return tableHtml\\n351|}\\n352|\\n353|/**\\n354| * 从HTML内容解析表格行（保留HTML标签）\\n355| */\\n356|const parseTableRowFromHtml = (htmlLine: string): string[] => {\\n357|  // 移除首尾的|\\n358|  const trimmed = htmlLine.replace(/^\\\\||\\\\|$/g, '''').trim()\\n359|  // 按|分割\\n360|  const cells = trimmed.split(/\\\\|/).map(cell => cell.trim())\\n361|  return cells\\n362|}\\n363|\\n364|/**\\n365| * 从纯文本解析表格行\\n366| */\\n367|const parseTableRowFromText = (line: string): string[] => {\\n368|  // 移除首尾的|\\n369|  const trimmed = line.replace(/^\\\\||\\\\|$/g, '''').trim()\\n370|  // 按|分割\\n371|  const cells = trimmed.split(/\\\\|/).map(cell => {\\n372|    let processed = cell.trim()\\n373|    // 移除Markdown格式标记，保留文本内容\\n374|    processed = processed.replace(/\\\\*\\\\*(.+?)\\\\*\\\\*/g, ''$1'') // 粗体\\n375|    processed = processed.replace(/\\\\*(.+?)\\\\*/g, ''$1'') // 斜体\\n376|    processed = processed.replace(/`(.+?)`/g, ''$1'') // 行内代码\\n377|    processed = processed.replace(/\\\\[(.+?)\\\\]\\\\(.+?\\\\)/g, ''$1'') // 链接\\n378|    return processed\\n379|  })\\n380|  return cells\\n381|}\\n382|\\n383|/**\\n384| * HTML转义\\n385| */\\n386|const escapeHtml = (text: string): string => {\\n387|  const div = typeof document !== ''undefined'' ? document.createElement(''div'') : null\\n388|  if (div) {\\n389|    div.textContent = text\\n390|    return div.innerHTML\\n391|  }\\n392|  // 降级方案\\n393|  return text\\n394|    .replace(/&/g, ''&amp;'')\\n395|    .replace(/</g, ''&lt;'')\\n396|    .replace(/>/g, ''&gt;'')\\n397|    .replace(/\\"/g, ''&quot;'')\\n398|    .replace(/''/g, ''&#39;'')\\n399|}\\n400|\\n401|/**\\n402| * 渲染文章内容\\n403| * 支持 markdown 和 html 格式\\n404| */\\n405|const renderContent = (content: BlogArticleContent): { html: string; toc: TocItem[] } => {\\n406|  if (!content.content) {\\n407|    return { html: '''', toc: [] }\\n408|  }\\n409|\\n410|  const format = content.format?.toLowerCase() || ''markdown''\\n411|\\n412|  // 如果是 HTML 格式，直接解析目录\\n413|  if (format === ''html'') {\\n414|    return parseToc(content.content)\\n415|  }\\n416|\\n417|  // 如果是 Markdown 格式，解析为 HTML\\n418|  if (format === ''markdown'') {\\n419|    try {\\n420|      let markdownContent = content.content\\n421|      \\n422|      // 处理 Gitee 图片 URL，修复 302 重定向问题\\n423|      markdownContent = markdownContent.replace(\\n424|        /!\\\\[([^\\\\]]*)\\\\]\\\\((https?:\\\\/\\\\/[^\\\\)]+gitee\\\\.com[^\\\\)]+)\\\\)/g,\\n425|        (match, alt, url) => {\\n426|          let processedUrl = url\\n427|          if (url.includes(''/raw/'')) {\\n428|            processedUrl = url.replace(/\\\\/raw\\\\/master\\\\//, ''/raw/master/'')\\n429|          }\\n430|          return `![${alt}](${processedUrl})`\\n431|        }\\n432|      )\\n433|      \\n434|      const html = marked(markdownContent, {\\n435|        breaks: true,\\n436|        gfm: true,\\n437|      }) as string\\n438|      \\n439|      // 修复表格：将段落中的表格文本转换为真正的表格\\n440|      const fixedHtml = fixTablesInParagraphs(html)\\n441|      \\n442|      // 将 Gitee 图片 URL 替换为后端代理 URL\\n443|      // 使用统一的 API 配置（已在顶部导入 API_BASE_URL）\\n444|      let processedHtml = fixedHtml.replace(\\n445|        /<img([^>]*src=[\\"'']([^\\"'']*gitee\\\\.com[^\\"'']*)[\\"''][^>]*)>/gi,\\n446|        (_match, attrs, src) => {\\n447|          // 规范化 API_BASE_URL：确保使用正确的路径\\n448|          let baseUrl = API_BASE_URL\\n449|          // 如果 API_BASE_URL 是 http://api 或 https://api（缺少端口号），转换为相对路径\\n450|          if (baseUrl.startsWith(''http://api'') || baseUrl.startsWith(''https://api'')) {\\n451|            baseUrl = ''''\\n452|          } else if (baseUrl === ''/'' || baseUrl === '''') {\\n453|            // 如果已经是相对路径，使用空字符串\\n454|            baseUrl = ''''\\n455|          }\\n456|          // 生成代理 URL：baseUrl + /api/images/proxy?url=...\\n457|          const proxyUrl = `${baseUrl}/api/images/proxy?url=${encodeURIComponent(src)}`\\n458|          attrs = attrs.replace(/src=[\\"''][^\\"'']*[\\"'']/, `src=\\"${proxyUrl}\\"`)\\n459|          return `<img${attrs}>`\\n460|        }\\n461|      )\\n462|      \\n463|      // 解析目录\\n464|      return parseToc(processedHtml)\\n465|    } catch (e) {\\n466|      console.error(''Markdown 解析失败:'', e)\\n467|      return { html: content.content, toc: [] }\\n468|    }\\n469|  }\\n470|\\n471|  // 其他格式，按纯文本处理\\n472|  return { html: content.content, toc: [] }\\n473|}\\n474|\\n475|const loadArticle = async () => {\\n476|  const id = Number(route.params.id)\\n477|  console.log(''🔍 [ArticleDetail] loadArticle 被调用，文章ID:'', id)\\n478|  if (!id) {\\n479|    error.value = ''无效的文章ID''\\n480|    console.warn(''🔍 [ArticleDetail] 无效的文章ID'')\\n481|    return\\n482|  }\\n483|\\n484|  try {\\n485|    loading.value = true\\n486|    error.value = null\\n487|    console.log(''🔍 [ArticleDetail] 开始加载文章数据，ID:'', id)\\n488|    const data = await blogApi.getArticleFull(id)\\n489|    console.log(''🔍 [ArticleDetail] 文章数据加载成功:'', data)\\n490|    articleData.value = data\\n491|    \\n492|    // 渲染内容并生成目录\\n493|    if (data.content) {\\n494|      const result = renderContent(data.content)\\n495|      renderedContent.value = result.html\\n496|      tocItems.value = result.toc\\n497|    }\\n498|    \\n499|    // 等待 DOM 更新后处理图片和代码块\\n500|    await nextTick()\\n501|    setTimeout(() => {\\n502|      handleImageErrors()\\n503|      handleCodeBlocks()\\n504|      initScrollListener()\\n505|    }, 100)\\n506|    console.log(''🔍 [ArticleDetail] 文章加载完成，内容已渲染'')\\n507|  } catch (err: any) {\\n508|    error.value = err.message || ''加载文章失败''\\n509|    console.error(''🔍 [ArticleDetail] 加载文章失败:'', err)\\n510|  } finally {\\n511|    loading.value = false\\n512|    console.log(''🔍 [ArticleDetail] loadArticle 执行完成，loading:'', loading.value)\\n513|  }\\n514|}\\n515|\\n516|/**\\n517| * 处理图片加载错误和样式\\n518| * 针对 Gitee 302 重定向问题，添加 referrer 策略和跨域处理\\n519| */\\n520|const handleImageErrors = () => {\\n521|  const images = markdownContent.value?.querySelectorAll(''img'') || document.querySelectorAll(''.markdown-body img'')\\n522|  images.forEach((img) => {\\n523|    const imgElement = img as HTMLImageElement\\n524|    \\n525|    // 处理 Gitee 图片的 302 重定向问题\\n526|    if (imgElement.src.includes(''gitee.com'')) {\\n527|      // 设置 referrer 策略，避免防盗链\\n528|      imgElement.setAttribute(''referrerpolicy'', ''no-referrer'')\\n529|      imgElement.setAttribute(''crossorigin'', ''anonymous'')\\n530|      \\n531|      // 如果是 raw 链接，尝试转换为正确的格式\\n532|      const originalSrc = imgElement.src\\n533|      if (originalSrc.includes(''/raw/master/'')) {\\n534|        // Gitee raw 链接可能需要添加参数或使用不同的格式\\n535|        // 尝试使用 blob 链接或代理\\n536|        imgElement.crossOrigin = ''anonymous''\\n537|      }\\n538|    }\\n539|    \\n540|    // 设置图片样式\\n541|    imgElement.style.display = ''block''\\n542|    imgElement.style.maxWidth = ''100%''\\n543|    imgElement.style.height = ''auto''\\n544|    imgElement.style.margin = ''1.5rem auto''\\n545|    imgElement.style.borderRadius = ''var(--border-radius-md, 0.5rem)''\\n546|    imgElement.style.boxShadow = ''var(--shadow-md, 0 4px 6px -1px rgba(0, 0, 0, 0.1))''\\n547|    imgElement.style.cursor = ''pointer''\\n548|    \\n549|    // 添加点击放大功能\\n550|    imgElement.addEventListener(''click'', () => {\\n551|      previewImage.value = imgElement.src\\n552|    })\\n553|    \\n554|    // 添加加载状态\\n555|    imgElement.style.opacity = ''0''\\n556|    imgElement.style.transition = ''opacity 0.3s ease-in-out''\\n557|    \\n558|    // 图片加载成功\\n559|    imgElement.onload = () => {\\n560|      imgElement.style.opacity = ''1''\\n561|      // 如果图片尺寸异常，可能是占位符\\n562|      if (imgElement.naturalWidth === 0 || imgElement.naturalHeight === 0) {\\n563|        console.warn(''图片尺寸异常，可能是占位符:'', imgElement.src)\\n564|      }\\n565|    }\\n566|    \\n567|    // 图片加载失败 - 尝试使用代理或显示占位符\\n568|    imgElement.onerror = () => {\\n569|      // 如果是 Gitee 图片，尝试使用代理\\n570|      if (imgElement.src.includes(''gitee.com'')) {\\n571|        const originalSrc = imgElement.src\\n572|        // 可以尝试使用后端代理或其他图床\\n573|        console.warn(''Gitee 图片加载失败，可能需要代理:'', originalSrc)\\n574|      }\\n575|      \\n576|      // 创建占位符\\n577|      const placeholder = document.createElement(''div'')\\n578|      placeholder.style.cssText = `\\n579|        display: block;\\n580|        width: 100%;\\n581|        min-height: 200px;\\n582|        background: var(--color-surface, #f8fafc);\\n583|        border: 2px dashed var(--color-border, #e2e8f0);\\n584|        border-radius: var(--border-radius-md, 0.5rem);\\n585|        margin: 1.5rem auto;\\n586|        display: flex;\\n587|        align-items: center;\\n588|        justify-content: center;\\n589|        color: var(--color-text-muted, #94a3b8);\\n590|        font-size: 0.875rem;\\n591|        flex-direction: column;\\n592|        gap: 0.5rem;\\n593|      `\\n594|      const errorText = document.createElement(''div'')\\n595|      errorText.textContent = `图片加载失败 (302 重定向)`\\n596|      const urlText = document.createElement(''div'')\\n597|      urlText.style.cssText = ''font-size: 0.75rem; word-break: break-all; padding: 0 1rem; text-align: center;''\\n598|      urlText.textContent = imgElement.src\\n599|      placeholder.appendChild(errorText)\\n600|      placeholder.appendChild(urlText)\\n601|      \\n602|      imgElement.parentNode?.replaceChild(placeholder, imgElement)\\n603|      console.warn(''图片加载失败:'', imgElement.src)\\n604|    }\\n605|    \\n606|    // 如果图片已经加载完成\\n607|    if (imgElement.complete) {\\n608|      if (imgElement.naturalWidth > 0 && imgElement.naturalHeight > 0) {\\n609|        imgElement.style.opacity = ''1''\\n610|      } else {\\n611|        // 触发错误处理\\n612|        imgElement.dispatchEvent(new Event(''error''))\\n613|      }\\n614|    }\\n615|  })\\n616|}\\n617|\\n618|const formatDate = (dateString: string) => {\\n619|  const date = new Date(dateString)\\n620|  return date.toLocaleDateString(''zh-CN'', {\\n621|    year: ''numeric'',\\n622|    month: ''2-digit'',\\n623|    day: ''2-digit'',\\n624|  })\\n625|}\\n626|\\n627|const getCategoryFromPath = (path: string) => {\\n628|  const parts = path.split(''/'')\\n629|  return parts[parts.length - 2] || ''未分类''\\n630|}\\n631|\\n632|/**\\n633| * 关闭图片预览\\n634| */\\n635|const closePreview = () => {\\n636|  previewImage.value = null\\n637|}\\n638|\\n639|/**\\n640| * 滚动到指定标题\\n641| */\\n642|const scrollToHeading = (id: string) => {\\n643|  const element = document.getElementById(id)\\n644|  if (element) {\\n645|    const headerOffset = 100 // Header 高度 + 偏移\\n646|    const elementPosition = element.getBoundingClientRect().top\\n647|    const offsetPosition = elementPosition + window.pageYOffset - headerOffset\\n648|\\n649|    window.scrollTo({\\n650|      top: offsetPosition,\\n651|      behavior: ''smooth''\\n652|    })\\n653|    \\n654|    // 使用 Vue Router 更新 hash\\n655|    router.replace({ hash: `#${id}` }).catch(() => {\\n656|      // 忽略导航重复的错误\\n657|    })\\n658|    activeTocId.value = id\\n659|  }\\n660|}\\n661|\\n662|/**\\n663| * 初始化滚动监听，高亮当前章节\\n664| * 注意：滚动时不会自动更新 URL，只在用户点击目录时更新\\n665| * 使用 requestAnimationFrame 优化性能\\n666| */\\n667|const initScrollListener = () => {\\n668|  // 清理之前的监听器和动画帧\\n669|  if (scrollHandler) {\\n670|    window.removeEventListener(''scroll'', scrollHandler)\\n671|    scrollHandler = null\\n672|  }\\n673|  if (scrollTimeout) {\\n674|    clearTimeout(scrollTimeout)\\n675|    scrollTimeout = null\\n676|  }\\n677|  if (rafId !== null) {\\n678|    cancelAnimationFrame(rafId)\\n679|    rafId = null\\n680|  }\\n681|  ticking = false\\n682|  \\n683|  const headings = tocItems.value.map(item => ({\\n684|    id: item.id,\\n685|    element: document.getElementById(item.id)\\n686|  })).filter(h => h.element !== null)\\n687|  \\n688|  if (headings.length === 0) return\\n689|  \\n690|  const handleScroll = () => {\\n691|    if (!ticking) {\\n692|      rafId = window.requestAnimationFrame(() => {\\n693|        const scrollPosition = window.scrollY + 150 // Header 高度 + 偏移\\n694|        \\n695|        // 从下往上查找当前应该高亮的标题\\n696|        for (let i = headings.length - 1; i >= 0; i--) {\\n697|          const heading = headings[i]\\n698|          if (heading.element) {\\n699|            const elementTop = heading.element.offsetTop\\n700|            if (scrollPosition >= elementTop) {\\n701|              // 只更新高亮状态，不更新 URL（避免频繁导航导致卡顿）\\n702|              if (activeTocId.value !== heading.id) {\\n703|                activeTocId.value = heading.id\\n704|              }\\n705|              break\\n706|            }\\n707|          }\\n708|        }\\n709|        \\n710|        ticking = false\\n711|      })\\n712|      \\n713|      ticking = true\\n714|    }\\n715|  }\\n716|  \\n717|  // 保存引用以便清理\\n718|  scrollHandler = handleScroll\\n719|  \\n720|  // 监听滚动事件（使用 passive 提高性能）\\n721|  window.addEventListener(''scroll'', handleScroll, { passive: true })\\n722|  \\n723|  // 初始检查（延迟执行，避免阻塞）\\n724|  scrollTimeout = window.setTimeout(() => {\\n725|    handleScroll()\\n726|  }, 100)\\n727|  \\n728|  // 检查 URL hash（仅在页面加载时）\\n729|  if (route.hash) {\\n730|    const hashId = route.hash.substring(1)\\n731|    const heading = headings.find(h => h.id === hashId)\\n732|    if (heading) {\\n733|      setTimeout(() => {\\n734|        scrollToHeading(hashId)\\n735|      }, 300)\\n736|    }\\n737|  }\\n738|}\\n739|\\n740|/**\\n741| * 处理代码块样式\\n742| */\\n743|const handleCodeBlocks = () => {\\n744|  const preBlocks = document.querySelectorAll(''.markdown-body pre'')\\n745|  preBlocks.forEach((pre) => {\\n746|    const preElement = pre as HTMLElement\\n747|    // 确保样式应用\\n748|    preElement.style.background = ''var(--color-surface, #f8fafc)''\\n749|    preElement.style.border = ''1px solid var(--color-border, #e2e8f0)''\\n750|    preElement.style.borderRadius = ''var(--border-radius-md, 0.5rem)''\\n751|    preElement.style.padding = ''1rem''\\n752|    preElement.style.overflowX = ''auto''\\n753|    preElement.style.overflowY = ''hidden''\\n754|    preElement.style.marginBottom = ''1.5rem''\\n755|    preElement.style.lineHeight = ''1.6''\\n756|    \\n757|    // 处理代码块内的 code 元素\\n758|    const codeElements = preElement.querySelectorAll(''code'')\\n759|    codeElements.forEach((code) => {\\n760|      const codeElement = code as HTMLElement\\n761|      codeElement.style.background = ''transparent''\\n762|      codeElement.style.padding = ''0''\\n763|      codeElement.style.borderRadius = ''0''\\n764|      codeElement.style.fontSize = ''0.875rem''\\n765|      codeElement.style.display = ''block''\\n766|      codeElement.style.whiteSpace = ''pre''\\n767|    })\\n768|  })\\n769|}\\n770|\\n771|// 监听路由变化，重新加载文章\\n772|watch(() => route.params.id, (newId, oldId) => {\\n773|  console.log(''🔍 [ArticleDetail] 路由参数变化:'', { newId, oldId, routePath: route.path })\\n774|  if (newId && newId !== oldId) {\\n775|    console.log(''🔍 [ArticleDetail] 检测到文章ID变化，清理旧数据并重新加载'')\\n776|    // 清理旧数据\\n777|    articleData.value = null\\n778|    renderedContent.value = ''''\\n779|    tocItems.value = []\\n780|    activeTocId.value = ''''\\n781|    error.value = null\\n782|    // 清理滚动监听器\\n783|    if (scrollHandler) {\\n784|      window.removeEventListener(''scroll'', scrollHandler)\\n785|      scrollHandler = null\\n786|    }\\n787|    if (scrollTimeout) {\\n788|      clearTimeout(scrollTimeout)\\n789|      scrollTimeout = null\\n790|    }\\n791|    if (rafId !== null) {\\n792|      cancelAnimationFrame(rafId)\\n793|      rafId = null\\n794|    }\\n795|    ticking = false\\n796|    // 重新加载文章\\n797|    loadArticle()\\n798|  }\\n799|}, { immediate: false })\\n800|\\n801|// 监听内容变化，重新处理样式\\n802|watch(() => articleData.value, async () => {\\n803|  if (articleData.value) {\\n804|    await nextTick()\\n805|    setTimeout(() => {\\n806|      handleImageErrors()\\n807|      handleCodeBlocks()\\n808|    }, 100)\\n809|  }\\n810|}, { deep: true })\\n811|\\n812|onMounted(() => {\\n813|  console.log(''🔍 [ArticleDetail] 组件已挂载，文章ID:'', route.params.id)\\n814|  initTheme()\\n815|  loadArticle()\\n816|})\\n817|\\n818|// 组件卸载时清理事件监听器\\n819|onUnmounted(() => {\\n820|  if (scrollHandler) {\\n821|    window.removeEvent