r\\">\\n6|        <button class=\\"back-btn\\" @click=\\"goHome\\" title=\\"返回主页\\">\\n7|          <span class=\\"back-icon\\">←</span>\\n8|          <span class=\\"back-text\\">返回</span>\\n9|        </button>\\n10|        <h2>会话列表</h2>\\n11|        <button class=\\"collapse-btn\\" @click=\\"toggleSidebar\\">{{ sidebarCollapsed ? ''展开'' : ''收起'' }}</button>\\n12|      </div>\\n13|      \\n14|      <div class=\\"sidebar-content\\" v-if=\\"!sidebarCollapsed\\">\\n15|        <button class=\\"new-chat-btn\\" @click=\\"createNewConversation\\">\\n16|          <span>+</span> 新建会话\\n17|        </button>\\n18|        \\n19|        <div class=\\"conversation-list\\">\\n20|          <div\\n21|            v-for=\\"conv in conversations\\"\\n22|            :key=\\"conv.id\\"\\n23|            class=\\"conversation-item\\"\\n24|            :class=\\"{ active: currentConversationId === conv.id }\\"\\n25|            @click=\\"selectConversation(conv.id)\\"\\n26|          >\\n27|            <div class=\\"conversation-title\\">{{ conv.title || ''未命名会话'' }}</div>\\n28|            <div class=\\"conversation-meta\\">\\n29|              <span>{{ conv.messageCount }} 条消息</span>\\n30|              <span v-if=\\"conv.lastMessageTime\\">\\n31|                {{ formatTime(conv.lastMessageTime) }}\\n32|              </span>\\n33|            </div>\\n34|          </div>\\n35|        </div>\\n36|      </div>\\n37|    </aside>\\n38|\\n39|    <!-- 主聊天区域 -->\\n40|    <main class=\\"chat-main\\">\\n41|      <!-- 移动端菜单按钮 -->\\n42|      <button class=\\"mobile-menu-btn\\" @click=\\"isMobileSidebarOpen = true\\" aria-label=\\"打开会话列表\\">\\n43|        ☰\\n44|      </button>\\n45|\\n46|      <!-- 消息列表 -->\\n47|      <div class=\\"messages-container\\" ref=\\"messagesContainerRef\\">\\n48|        <!-- 欢迎消息 -->\\n49|        <div v-if=\\"messages.length === 0\\" class=\\"welcome-section\\">\\n50|          <div class=\\"welcome-message\\">\\n51|            <h2>你好，我是 AI 助手</h2>\\n52|            <p>有什么可以帮助你的吗？