     ></textarea>\\n140|            <div class=\\"input-actions\\">\\n141|              <button\\n142|                type=\\"button\\"\\n143|                class=\\"action-btn\\"\\n144|                title=\\"附件\\"\\n145|                @click=\\"handleAttach\\"\\n146|              >\\n147|                📎\\n148|              </button>\\n149|              <button\\n150|                type=\\"submit\\"\\n151|                class=\\"send-btn\\"\\n152|                :disabled=\\"!inputText.trim() || isLoading\\"\\n153|                title=\\"发送 (Enter)\\"\\n154|              >\\n155|                <span v-if=\\"!isLoading\\">发送</span>\\n156|                <span v-else class=\\"loading-spinner\\">⏳</span>\\n157|              </button>\\n158|            </div>\\n159|          </div>\\n160|        </form>\\n161|      </div>\\n162|    </main>\\n163|  </div>\\n164|</template>\\n165|\\n166|<script setup lang=\\"ts\\">\\n167|import { ref, onMounted, onUnmounted, nextTick } from ''vue''\\n168|import { useRouter } from ''vue-router''\\n169|import {\\n170|  getConversations,\\n171|  getConversationDetail,\\n172|  queryRAG,\\n173|  getOrCreateGuestId,\\n174|  type Conversation,\\n175|  type ConversationMessage,\\n176|  type RAGEvent,\\n177|} from ''@/services/conversation''\\n178|\\n179|const router = useRouter()\\n180|\\n181|// 状态管理\\n182|const conversations = ref<Conversation[]>([])\\n183|const messages = ref<ConversationMessage[]>([])\\n184|const currentConversationId = ref<number | null>(null)\\n185|const inputText = ref('''')\\n186|const isLoading = ref(false)\\n187|const sidebarCollapsed = ref(false)\\n188|const messagesContainerRef = ref<HTMLElement | null>(null)\\n189|const isMobileSidebarOpen = ref(false)\\n190|\\n191|const toggleSidebar = () => {\\n192|  if (window.innerWidth <= 768) {\\n193|    isMobileSidebarOpen.value = !isMobileSidebarOpen.value\\n194|  } else {\\n195|    sidebarCollapsed.value = !sidebarCollapsed.value\\n196|  }\\n197|}\\n198|const textareaRef = ref<HTMLTextAreaElement | null>(null)\\n199|let cancelQuery: (() => void) | null = null\\n200|\\n201|// 技能卡片配置\\n202|const skillCards = [\\n203|  { id: ''search'', icon: ''🔍'', label: ''文章检索'', prompt: ''帮我检索相关文章'' },\\n204|  // { id: ''image'', icon: ''🎨'', label: ''图像生成'', prompt: ''帮我生成一张图片'' },\\n205|  // { id: ''write'', icon: ''✍️'', label: ''帮我写作'', prompt: ''帮我写一篇文章'' },\\n206|  // { id: ''translate'', icon: ''🌐'', label: ''翻译'', prompt: ''帮我翻译这段文字'' },\\n207|  // { id: ''code'', icon: ''💻'', label: ''编程'', prompt: ''帮我写代码'' },\\n208|  // { id: ''research'', icon: ''🔍'', label: ''深入研究'', prompt: ''深入研究这个话题'' },\\n209|]\\n210|\\n211|// 处理技能卡片点击\\n212|const handleSkillClick = (skill: typeof skillCards[0]) => {\\n213|  inputText.value = skill.prompt\\n214|  textareaRef.value?.focus()\\n215|  // 可选：自动提交\\n216|  // handleSubmit()\\n217|}\\n218|\\n219|// 处理附件\\n220|const handleAttach = () => {\\n221|  // TODO: 实现附件功能\\n222|  console.log(''附件功能待实现'')\\n223|}\\n224|\\n225|// 加载会话列表\\n226|const loadConversations = async () => {\\n227|  try {\\n228|    const data = await getConversations({ status: 1, limit: 50 })\\n229|    conversations.value = data\\n230|  } catch (error) {\\n231|    console.error(''加载会话列表失败:'', error)\\n232|  }\\n233|}\\n234|\\n235|// 选择会话\\n236|const selectConversation = async (conversationId: number) => {\\n237|  currentConversationId.value = conversationId\\n238|  try {\\n239|    const detail = await getConversationDetail(conversationId)\\n240|    messages.value = detail.messages || []\\n241|    scrollToBottom()\\n242|  } catch (error) {\\n243|    console.error(''加载会话详情失败:'', error)\\n244|  }\\n245|}\\n246|\\n247|// 创建新会话\\n248|const createNewConversation = () => {\\n249|  currentConversationId.value = null\\n250|  messages.value = []\\n251|  inputText.value = ''''\\n252|}\\n253|\\n254|// 处理提交\\n255|const handleSubmit = async () => {\\n256|  const question = inputText.value.trim()\\n257|  if (!question || isLoading.value) return\\n258|\\n259|  // 添加用户消息到界面\\n260|  const userMessage: ConversationMessage = {\\n261|    id: Date.now(),\\n262|    conversationId: currentConversationId.value || 0,\\n263|    role: ''user'',\\n264|    content: question,\\n265|    createdTime: new Date().toISOString(),\\n266|  }\\n267|  messages.value.push(userMessage)\\n268|  inputText.value = ''''\\n269|  autoResize()\\n270|  scrollToBottom()\\n271|\\n272|  // 开始加载\\n273|  isLoading.value = true\\n274|  let assistantMessageId = Date.now() + 1\\n275|  let assistantContent = ''''\\n276|\\n277|  // 创建助手消息占位\\n278|  const assistantMessage: ConversationMessage = {\\n279|    id: assistantMessageId,\\n280|    conversationId: currentConversationId.value || 0,\\n281|    role: ''assistant'',\\n282|    content: '''',\\n283|    createdTime: new Date().toISOString(),\\n284|  }\\n285|  messages.value.push(assistantMessage)\\n286|\\n287|  // 执行 RAG 查询\\n288|  cancelQuery = queryRAG(\\n289|    {\\n290|      question,\\n291|      architecture: ''naive'',\\n292|      conversationId: currentConversationId.value || undefined,\\n293|      topK: 5, // 检索5个文档，增加引用数量\\n294|    },\\n295|    (event: RAGEvent) => {\\n296|      if (event.type === ''answer_chunk'') {\\n297|        // 流式更新答案\\n298|        assistantContent += event.data\\n299|        const msg = messages.value.find((m) => m.id === assistantMessageId)\\n300|        if (msg) {\\n301|          msg.content = assistantContent\\n302|        }\\n303|        scrollToBottom()\\n304|      } else if (event.type === ''sources'') {\\n305|        // 更新引用来源\\n306|        const msg = messages.value.find((m) => m.id === assistantMessageId)\\n307|        if (msg) {\\n308|          msg.sources = event.data\\n309|        }\\n310|      } else if (event.type === ''done'') {\\n311|        // 查询完成\\n312|        isLoading.value = false\\n313|        if (event.data.conversation_id) {\\n314|          currentConversationId.value = event.data.conversation_id\\n315|          // 重新加载会话列表\\n316|          loadConversations()\\n317|        }\\n318|        cancelQuery = null\\n319|      } else if (event.type === ''error'') {\\n320|        // 错误处理\\n321|        isLoading.value = false\\n322|        const msg = messages.value.find((m) => m.id === assistantMessageId)\\n323|        if (msg) {\\n324|          msg.content = `错误: ${event.data}`\\n325|        }\\n326|        cancelQuery = null\\n327|      }\\n328|    },\\n329|    (error) => {\\n330|      isLoading.value = false\\n331|      const msg = messages.value.find((m) => m.id === assistantMessageId)\\n332|      if (msg) {\\n333|        msg.content = `请求失败: ${error.message}`\\n334|      }\\n335|      cancelQuery = null\\n336|    }\\n337|  )\\n338|}\\n339|\\n340|// 自动调整文本框高度\\n341|const autoResize = () => {\\n342|  nextTick(() => {\\n343|    if (textareaRef.value) {\\n344|      textareaRef.value.style.height = ''auto''\\n345|      textareaRef.value.style.height = `${textareaRef.value.scrollHeight}px`\\n346|    }\\n347|  })\\n348|}\\n349|\\n350|// 滚动到底部\\n351|const scrollToBottom = () => {\\n352|  nextTick(() => {\\n353|    if (messagesContainerRef.value) {\\n354|      messagesContainerRef.value.scrollTop = messagesContainerRef.value.scrollHeight\\n355|    }\\n356|  })\\n357|}\\n358|\\n359|// 格式化消息（支持 Markdown）\\n360|const formatMessage = (content: string): string => {\\n361|  // 简单的 Markdown 转 HTML（可以后续使用 marked 库）\\n362|  return content\\n363|    .replace(/\\\\n/g, ''<br>'')\\n364|    .replace(/\\\\*\\\\*(.*?)\\\\*\\\\*/g, ''<strong>$1</strong>'')\\n365|    .replace(/\\\\*(.*?)\\\\*/g, ''<em>$1</em>'')\\n366|    .replace(/`(.*?)`/g, ''<code>$1</code>'')\\n367|}\\n368|\\n369|// 格式化时间\\n370|const formatTime = (time: string): string => {\\n371|  const date = new Date(time)\\n372|  const now = new Date()\\n373|  const diff = now.getTime() - date.getTime()\\n374|  const minutes = Math.floor(diff / 60000)\\n375|  const hours = Math.floor(diff / 3600000)\\n376|  const days = Math.floor(diff / 86400000)\\n377|\\n378|  if (minutes < 1) return ''刚刚''\\n379|  if (minutes < 60) return `${minutes}分钟前`\\n380|  if (hours < 24) return `${hours}小时前`\\n381|  if (days < 7) return `${days}天前`\\n382|  return date.toLocaleDateString(''zh-CN'')\\n383|}\\n384|\\n385|// 去重引用来源（按文章ID去重，每个文章只显示一次）\\n386|const getUniqueSources = (sources: any[]): any[] => {\\n387|  if (!sources || !Array.isArray(sources)) return []\\n388|  \\n389|  const seen = new Map<number, any>()\\n390|  for (const source of sources) {\\n391|    const articleId = source.article_id\\n392|    if (articleId && !seen.has(articleId)) {\\n393|      // 保留第一个出现的引用（通常是最相关的）\\n394|      seen.set(articleId, source)\\n395|    }\\n396|  }\\n397|  \\n398|  return Array.from(seen.values())\\n399|}\\n400|\\n401|// 返回主页\\n402|const goHome = () => {\\n403|  router.push(''/'')\\n404|}\\n405|\\n406|// 初始化\\n407|onMounted(() => {\\n408|  // 确保有访客ID\\n409|  getOrCreateGuestId()\\n410|  // 加载会话列表\\n411|  loadConversations()\\n412|})\\n413|\\n414|// 清理\\n415|onUnmounted(() => {\\n416|  if (cancelQuery) {\\n417|    cancelQuery()\\n418|  }\\n419|})\\n420|</script>\\n421|\\n422|<style scoped>\\n423|.chat-container {\\n424|  display: flex;\\n425|  height: 100vh;\\n426|  width: 100%;\\n427|  background: var(--color-background);\\n428|  overflow: hidden;\\n429|}\\n430|\\n431|/* 侧边栏 */\\n432|.chat-sidebar {\\n433|  width: var(--chat-sidebar-width, 280px);\\n434|  border-right: var(--chat-sidebar-border, 1px solid var(--color-border));\\n435|  background: var(--chat-sidebar-bg, var(--color-surface));\\n436|  display: flex;\\n437|  flex-direction: column;\\n438|  transition: transform 0.3s ease-in-out, width 0.3s ease-in-out;\\n439|  overflow: hidden;\\n440|}\\n441|\\n442|.chat-sidebar.collapsed {\\n443|  width: 60px;\\n444|}\\n445|\\n446|/* 移动端侧边栏样式 */\\n447|@media (max-width: 768px) {\\n448|  .chat-sidebar {\\n449|    position: fixed;\\n450|    top: 0;\\n451|    left: 0;\\n452|    bottom: 0;\\n453|    z-index: 1000;\\n454|    transform: translateX(-100%);\\n455|    box-shadow: var(-