der: none;\\n541|  color: var(--color-text-secondary);\\n542|  cursor: pointer;\\n543|  padding: var(--spacing-xs);\\n544|  font-size: var(--font-size-sm);\\n545|  flex-shrink: 0;\\n546|}\\n547|\\n548|.collapse-btn:hover {\\n549|  color: var(--color-primary);\\n550|}\\n551|\\n552|.sidebar-content {\\n553|  flex: 1;\\n554|  overflow-y: auto;\\n555|  padding: var(--spacing-md, 16px);\\n556|  padding-top: 0;\\n557|}\\n558|\\n559|.new-chat-btn {\\n560|  width: 100%;\\n561|  padding: var(--spacing-md);\\n562|  background: var(--color-primary);\\n563|  color: white;\\n564|  border: none;\\n565|  border-radius: var(--border-radius-md, var(--chat-input-button-radius, 16px));\\n566|  cursor: pointer;\\n567|  font-size: var(--font-size-base);\\n568|  font-weight: var(--font-weight-medium);\\n569|  margin-bottom: var(--spacing-md);\\n570|  transition: background var(--transition);\\n571|}\\n572|\\n573|.new-chat-btn:hover {\\n574|  background: var(--color-accent);\\n575|}\\n576|\\n577|.conversation-list {\\n578|  display: flex;\\n579|  flex-direction: column;\\n580|  gap: var(--spacing-xs);\\n581|}\\n582|\\n583|.conversation-item {\\n584|  padding: var(--spacing-md);\\n585|  border-radius: var(--border-radius-md);\\n586|  cursor: pointer;\\n587|  transition: background var(--transition);\\n588|  background: var(--color-background);\\n589|}\\n590|\\n591|.conversation-item:hover {\\n592|  background: var(--color-surface);\\n593|}\\n594|\\n595|.conversation-item.active {\\n596|  background: var(--color-primary);\\n597|  color: white;\\n598|}\\n599|\\n600|.conversation-title {\\n601|  font-weight: var(--font-weight-medium);\\n602|  margin-bottom: var(--spacing-xs);\\n603|  overflow: hidden;\\n604|  text-overflow: ellipsis;\\n605|  white-space: nowrap;\\n606|}\\n607|\\n608|.conversation-meta {\\n609|  font-size: var(--font-size-sm);\\n610|  color: var(--color-text-secondary);\\n611|  display: flex;\\n612|  justify-content: space-between;\\n613|}\\n614|\\n615|.conversation-item.active .conversation-meta {\\n616|  color: rgba(255, 255, 255, 0.8);\\n617|}\\n618|\\n619|/* 主聊天区域 */\\n620|.chat-main {\\n621|  flex: 1;\\n622|  display: flex;\\n623|  flex-direction: column;\\n624|  background: var(--color-background);\\n625|  overflow: hidden;\\n626|  position: relative;\\n627|}\\n628|\\n629|.messages-container {\\n630|  flex: 1;\\n631|  overflow-y: auto;\\n632|  padding: var(--spacing-lg, 24px);\\n633|  display: flex;\\n634|  flex-direction: column;\\n635|  gap: var(--spacing-lg, 24px);\\n636|  position: relative;\\n637|}\\n638|\\n639|/* 欢迎区域 */\\n640|.welcome-section {\\n641|  display: flex;\\n642|  flex-direction: column;\\n643|  align-items: center;\\n644|  justify-content: center;\\n645|  min-height: 60vh;\\n646|  padding: var(--spacing-2xl, 48px) var(--spacing-lg);\\n647|  text-align: center;\\n648|}\\n649|\\n650|.welcome-message {\\n651|  margin-bottom: var(--spacing-2xl, 48px);\\n652|}\\n653|\\n654|.welcome-message h2 {\\n655|  font-size: var(--font-size-xl, 26px);\\n656|  font-weight: var(--font-weight-semibold, 600);\\n657|  color: var(--color-text-primary);\\n658|  margin-bottom: var(--spacing-sm);\\n659|  line-height: 1.4;\\n660|}\\n661|\\n662|.welcome-message p {\\n663|  font-size: var(--font-size-base);\\n664|  color: var(--color-text-secondary);\\n665|  margin: 0;\\n666|}\\n667|\\n668|/* 技能卡片 */\\n669|.skill-cards {\\n670|  display: flex;\\n671|  flex-wrap: wrap;\\n672|  gap: var(--spacing-sm, 12px);\\n673|  justify-content: center;\\n674|  max-width: 800px;\\n675|  margin: 0 auto;\\n676|}\\n677|\\n678|.skill-card {\\n679|  display: inline-flex;\\n680|  align-items: center;\\n681|  gap: 8px;\\n682|  padding: var(--chat-skill-card-padding, 10px 15px);\\n683|  background: var(--chat-skill-card-bg, transparent);\\n684|  border: var(--chat-skill-card-border, 0.8px solid rgba(0, 0, 0, 0.08));\\n685|  border-radius: var(--chat-skill-card-radius, var(--border-radius-xxl, 32px));\\n686|  color: var(--color-text-primary);\\n687|  font-size: var(